statement.tex:
\begin{enumerate}
  \item $y=x^{\frac1x}\ (x>0)$ を微分し，$y$ が最大となる $x$ を求めよ．
  \item アステロイド $x=\cos^3t,\ y=\sin^3t\ \bigl(0<t<\frac\pi2\bigr)$ 上の点における接線が $x$ 軸，$y$ 軸と交わる点を A，B とするとき，AB の長さは一定であることを示せ．
  \item 曲線 $x^2+xy+y^2=7$ 上の点 $(1,2)$ における接線の方程式を求めよ．
\end{enumerate}

$f(x)=x^2\sin\dfrac1x\ (x\neq0)$，$f(0)=0$ とする．
\begin{enumerate}
  \item $f(x)$ は $x=0$ で微分可能であることを示し，$f'(0)$ を求めよ．
  \item $x\neq0$ での $f'(x)$ を求め，$\displaystyle\lim_{x\to0}f'(x)$ は存在しないことを示せ．
\end{enumerate}

$f(x)=\dfrac{x^2-x+1}{x-1}$ とする．
\begin{enumerate}
  \item $f(x)$ の極値と，$y=f(x)$ の漸近線を求めよ．
  \item 方程式 $f(x)=k$ の実数解の個数を $k$ の値によって分類せよ．
\end{enumerate}

$a$ を定数とし，$f(x)=\dfrac{x+a}{x^2+1}$ とする．
\begin{enumerate}
  \item $f(x)$ の最大値と最小値を $a$ で表せ．
  \item 最大値が1となる $a$ を求め，そのときの最小値を求めよ．
\end{enumerate}

曲線 $y=\log x$ 上の点 A$(1,0)$ と，点 Q$(t,\log t)\ (t\neq1)$ における法線の交点を R とする．
\begin{enumerate}
  \item A における法線の方程式を求めよ．
  \item $t\to1$ のとき R が近づく点を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $3^\pi$ と $\pi^3$ の大小を比較せよ．
  \item $x<y$ を満たす自然数の組で $x^y=y^x$ となるものをすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\log x$ が上に凸であることを使って，正の数 $a,b$ について $a^{\frac13}b^{\frac23}\leqq\dfrac{a}{3}+\dfrac{2b}{3}$ を示せ．
  \item $\triangle ABC$ において $\sin A+\sin B+\sin C\leqq\dfrac{3\sqrt3}2$ を示せ（$\sin x$ が $0<x<\pi$ で上に凸であることを用いてよい）．
\end{enumerate}

\begin{enumerate}
  \item $0<a<b$ のとき，$\dfrac{b-a}{b}<\log b-\log a<\dfrac{b-a}{a}$ を示せ．
  \item 自然数 $n$ に対して $\Bigl(1+\dfrac1n\Bigr)^n<e<\Bigl(1+\dfrac1n\Bigr)^{n+1}$ を示せ．
\end{enumerate}

$x>0$ に対し $f(x)=\dfrac{\log x}{x^2}$ とする．
\begin{enumerate}
  \item $n=1,2,\dots$ に対し $f^{(n)}(x)=\dfrac{a_n+b_n\log x}{x^{n+2}}$ と表されることを示し，$a_n,b_n$ の漸化式を求めよ．
  \item $h_n=\displaystyle\sum_{k=1}^n\frac1k$ とおく．$a_n,b_n$ の一般項を $h_n$ を用いて表せ．
\end{enumerate}

\begin{enumerate}
  \item $0<\theta<\dfrac\pi2$ のとき，$2\sin\theta+\tan\theta>3\theta$ を証明せよ．
  \item (1) を用いて $\pi<2+\dfrac{2\sqrt3}{3}$ を示せ．
\end{enumerate}

$a$ を定数とし，$f(x)=\dfrac{a-\sin x}{a+\cos x}$ とする．
\begin{enumerate}
  \item $f(x)$ が $0<x<\dfrac\pi2$ の範囲で極大値をもつような $a$ の値の範囲を求めよ．
  \item $f'(x)=0$ となる点 $x$ では $f(x)=\dfrac{\cos x}{\sin x}$ となることを示せ．
  \item 極大値が $2+\sqrt3$ となるときの $a$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき $\dfrac1{x+1}<\log(x+1)-\log x<\dfrac1x$ を示せ．
  \item $x>0$ のとき $\Bigl(1+\dfrac1x\Bigr)^x<e<\Bigl(1+\dfrac1x\Bigr)^{x+1}$ を示せ．
  \item 自然数 $n$ に対し $0<e-\Bigl(1+\dfrac1n\Bigr)^n<\dfrac{e}{n+1}$ を示せ．
\end{enumerate}

半径 $a$ の球に外接する直円すいについて，
\begin{enumerate}
  \item 底面の半径を $x$ とするとき，高さ $h$ を $x$ で表せ．
  \item 直円すいの体積 $V$ と表面積（底面を含む）$S$ の間に $V=\dfrac13aS$ が成り立つことを示せ．
  \item $S$ の最小値と，そのときの $x$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $y=\dfrac{e^x}{x^2}$ の概形をかけ．
  \item 定数 $k$ に対して，方程式 $e^x=kx^2$ の異なる実数解の個数を求めよ．
\end{enumerate}

関数 $f(x)=\dfrac{x^2+ax+b}{x^2+1}$ は $x=1$ で極大値 $3$ をとる．
\begin{enumerate}
  \item $a,b$ の値を求めよ．
  \item $f(x)$ の極小値を求めよ．
  \item 曲線 $y=f(x)$，直線 $y=1$，直線 $x=1$ で囲まれた部分の面積を求めよ．
\end{enumerate}

曲線 $y=\log x$ 上の点 $(t,\log t)\ (1\leqq t\leqq e)$ における接線を $l$ とする．
\begin{enumerate}
  \item $l$ は $1\leqq x\leqq e$ で $x$ 軸より上にあることを示せ．
  \item $l$，$x$ 軸，2直線 $x=1$，$x=e$ で囲まれた台形の面積 $S(t)$ を求めよ．
  \item $S(t)$ の最小値と最大値を求めよ．
\end{enumerate}

$a>1$ を定数とする．
\begin{enumerate}
  \item 不等式 $a^x\geqq x^2$ がすべての正の数 $x$ に対して成り立つような $a$ の範囲を求めよ．
  \item 不等式 $a^x\geqq x^a$ がすべての正の数 $x$ に対して成り立つような $a$ を求めよ．
\end{enumerate}

$k$ を正の整数とし，$(2k-1)\pi\leqq x\leqq2k\pi$ で定義された2曲線 $C_1:y=\cos x$，$C_2:y=\dfrac{1-x^2}{1+x^2}$ を考える．
\begin{enumerate}
  \item $x$ が $C_1$ と $C_2$ の共有点の $x$ 座標であることは，$\tan\dfrac x2=-x$ と同値であることを示せ．
  \item 共有点はただ1つであることを示せ．その $x$ 座標を $x_k$ とする．
  \item $\displaystyle\lim_{k\to\infty}k\{x_k-(2k-1)\pi\}$ を求めよ．
\end{enumerate}

$n$ を自然数とし，$\cos n\theta=f_n(\cos\theta)$ をみたす $n$ 次の整数係数多項式 $f_n(x)$ を考える（$f_0=1$）．
\begin{enumerate}
  \item $f_{n+1}(x)=2xf_n(x)-f_{n-1}(x)$ を示し，$f_n$ の最高次の係数を求めよ．
  \item 自然数 $m,n$ に対し $f_m(f_n(x))=f_{mn}(x)$ を示せ．
  \item $f_n(x)$ の係数の絶対値の和は $\dfrac{(1+\sqrt2)^n+(1-\sqrt2)^n}2$ であることを示せ．
\end{enumerate}

2以上の自然数 $n$ に対し $f_n(x)=2-x-2e^{-nx}$ とする．
\begin{enumerate}
  \item $f_n(x)$ の最大値とそのときの $x$ を求めよ．
  \item $f_n(x)=0$ の正の解はただ1つであることを示し，それを $a_n$ とするとき $\displaystyle\lim_{n\to\infty}a_n=2$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}\int_0^{a_n}f_n(x)\,dx$ を求めよ．
\end{enumerate}

2曲線 $C_1:y=e^x$，$C_2:y=\log x$ について，
\begin{enumerate}
  \item 原点から $C_1$，$C_2$ に引いた接線をそれぞれ求めよ．
  \item $C_1$，$C_2$ の両方に接する直線はちょうど2本あることを示し，それらの傾きの積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき $\log\Bigl(1+\dfrac1x\Bigr)>\dfrac1{x+1}$ を示し，$f(x)=x\log\Bigl(1+\dfrac1x\Bigr)$ が増加関数であることを示せ．
  \item $\Bigl(1+\dfrac{99}{100}\Bigr)^{\frac{100}{99}}$ と $\Bigl(1+\dfrac{100}{99}\Bigr)^{\frac{99}{100}}$ の大小を比較せよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)=x^{\log x}$（$x>0$）の導関数を求めよ．
  \item $y=(\sin x)^{\cos x}$（$0<x<\frac\pi2$）の導関数を求めよ．
  \item 曲線 $x^{\frac23}+y^{\frac23}=1$（$x>0,\ y>0$）について，導関数 $y'$ と2階導関数 $y''$ を $x,y$ で表せ．
\end{enumerate}

$xy$ 平面上の曲線 $C$ を $x=\cos^3t$，$y=\sin^3t$（$0<t<\frac\pi2$）で定義する．
\begin{enumerate}
  \item $\dfrac{dy}{dx}$，$\dfrac{d^2y}{dx^2}$ を $t$ で表せ．
  \item 曲線 $C$ 上の点 P における接線と $x$ 軸，$y$ 軸との交点をそれぞれ Q，R とするとき，線分 QR の長さは一定であることを示せ．
\end{enumerate}

関数 $f(x)=\dfrac{x^2+ax+b}{x-c}$ が $x=c+\alpha$（$\alpha>0$）で極値をとるとき，以下の問に答えよ．
\begin{enumerate}
  \item $f(x)$ は $x=c-\alpha$ でも極値をとることを示せ．
  \item $f(x)$ の極大値から極小値を引いた値を $\alpha$ で表せ．
  \item 2つの極値をとる点を結ぶ線分の中点は，曲線 $y=f(x)$ の斜めの漸近線上にあることを示せ．
\end{enumerate}

曲線 $C:\ y=\log x$ 上の異なる2点 A$(a,\log a)$，P$(t,\log t)$ における $C$ のそれぞれの法線の交点を Q として，線分 AQ の長さを $L_a(t)$ で表す．さらに $r(a)=\displaystyle\lim_{t\to a}L_a(t)$ と定義する．
\begin{enumerate}
  \item $r(a)$ を求めよ．
  \item $a$ が正の実数全体を動くとき，$r(a)$ の最小値を求めよ．
\end{enumerate}

$a$ は定数とする．関数 $f(x)=\sin x\cos x-a\cos x+(2a-1)x$（$-\frac\pi2<x<\frac\pi2$）について，
\begin{enumerate}
  \item $f'(x)$ を $\sin x$ の式で表せ．
  \item $f(x)$ が極大値と極小値をもつように，定数 $a$ の値の範囲を定めよ．
  \item $y=f(x)$ のグラフが変曲点をもち，その変曲点における接線の傾きが1であるように，定数 $a$ の値を定めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき，$\dfrac{x^3}{e^x}<\dfrac{24}x$ を示せ．
  \item (1) を用いて，$\displaystyle\lim_{x\to\infty}x^3e^{-x}=0$ を示せ．
  \item $k$ を実数とするとき，$x$ の方程式 $x^2-x-1=ke^x$ の実数解の個数を求めよ．
\end{enumerate}

関数 $f(x)=x^2e^{-x}$ について，次の問に答えよ．
\begin{enumerate}
  \item 関数 $f(x)$ の増減，極値を調べて，曲線 $y=f(x)$ の概形を述べよ．
  \item $x$ 軸上の点 $(a,0)$ から，曲線 $y=f(x)$ への接線を3本ひくことができるような $a$ の値の範囲を求めよ．
\end{enumerate}

$x>0$ の範囲で，関数 $f(x)=\dfrac{\sin x}x$ を考える．
\begin{enumerate}
  \item $f(x)$ は $0<x\leqq\pi$ において減少することを示せ．
  \item $n$ を自然数とする．$f(x)$ が極値をとる $x$ は，区間 $n\pi<x<n\pi+\frac\pi2$ にちょうど1つずつ存在することを示せ．
  \item (2) の $x$ を $x_n$ とするとき，$\displaystyle\lim_{n\to\infty}(x_n-n\pi)$ を求めよ．
\end{enumerate}

関数 $f(x)$ は任意の実数 $x$ に対して定義されているとする．
\begin{enumerate}
  \item $f(x)$ が $x=a$ において微分可能であることの定義を述べよ．
  \item $f(x)=x\sin\dfrac1x$（$x\neq0$），$f(0)=0$ とする．$f(x)$ は $x=0$ で連続であるが微分可能でないことを示せ．
  \item 関数 $f(x)=\sin x$ が $x=a$ において微分可能であることを，(1) の定義を用いて証明せよ．
\end{enumerate}

$x>0$ に対し $f(x)=\dfrac{\log x}{x^2}$ とする．
\begin{enumerate}
  \item $n=0,1,2,\dots$ に対し $f(x)$ の第 $n$ 次導関数は，数列 $\{a_n\}$，$\{b_n\}$ を用いて $f^{(n)}(x)=\dfrac{a_n+b_n\log x}{x^{n+2}}$ と表されることを示し，$a_n,b_n$ に関する漸化式を求めよ（$a_0=0,\ b_0=1$）．
  \item $h_n=\displaystyle\sum_{k=1}^n\frac1k$ とおく．$h_n$ を用いて $a_n,b_n$ の一般項を求めよ．
\end{enumerate}

関数 $f(x)$ はすべての実数 $x$ に対して定義された関数で，任意の実数 $x,y$ に対して $f(x+y)=f(x)+f(y)+2xy$ を満たし，$f'(0)=a$ である．
\begin{enumerate}
  \item $f(0)$ を求めよ．
  \item $f(x)$ は微分可能な関数であることを示し，$f'(x)$ を求めよ．
  \item $f(x)$ を求めよ．
\end{enumerate}

定数でない多項式 $f(x)$ が等式 $f(x)=\{f'(x)\}^2$ を満たすとき，
\begin{enumerate}
  \item $f(x)$ の次数を求めよ．
  \item $f(x)$ を求め，方程式 $f(x)=0$ は重解をもつことを示せ．
\end{enumerate}

放物線 $y=x^2$ 上に3点A，B，Cがあり，$\triangle$ABC は $\angle$B を直角とする直角二等辺三角形である．A，B，C の $x$ 座標をそれぞれ $a,b,c$ とするとき $a<b<c$ をみたし，直線BCの傾き $m$ は正であるとする．
\begin{enumerate}
  \item $a,b,c$ をそれぞれ $m$ の分数式で表せ．
  \item $\triangle$ABC の面積 $T$ を $m$ で表し，$T$ の最小値とそのときの $m$ を求めよ．
\end{enumerate}

関数 $g(x)=xe^x+(2-e^x)\log(2-e^x)$（$x<\log2$）について，次の問に答えよ．
\begin{enumerate}
  \item $g(x)$ の増減と極値を調べ，$y=g(x)$ のグラフの概形を描け．ただし，グラフの凹凸は調べなくてよい．必要なら，$\displaystyle\lim_{x\to-\infty}xe^x=0$，$\displaystyle\lim_{u\to+0}u\log u=0$ を用いてもよい．
  \item 曲線 $C_1:y=e^x+k$ と曲線 $C_2:y=2x-e^x$ が共通接線をもつような，実数 $k$ の範囲を求めよ．また，共通接線がちょうど1本となる $k$ を求めよ．
\end{enumerate}

曲線 $C:y=(2-\cos x)\sin x$（$0\leqq x\leqq2\pi$）がある．次の問いに答えなさい．
\begin{enumerate}
  \item 曲線 $C$ の概形をかきなさい．ただし，凹凸は調べなくてよい．
  \item 曲線 $C$ 上に2点をとり，その2点を通る直線を考える．この直線の傾きがとり得る範囲を求めなさい．ただし，2点が一致するときは，その点における接線を考えるものとする．
\end{enumerate}

\begin{enumerate}
  \item $a,b$ を異なる実数とし，関数 $f(x)$ が $a,b$ を含む区間で第2次導関数 $f''(x)$ を持ち $f''(x)>0$ が成り立つものとする．このとき $0\leqq t\leqq1$ に対して，$tf(a)+(1-t)f(b)\geqq f(ta+(1-t)b)$ が成り立つことを示せ．
  \item (1) の条件の下で（3点を含む区間で），$\dfrac{f(a)+f(b)+f(c)}3\geqq f\left(\dfrac{a+b+c}3\right)$ を示せ．
  \item $f(x)=x\log x$ に (2) を適用することにより，正の数 $a,b,c$ に対して，$a^ab^bc^c\geqq\left(\dfrac{a+b+c}3\right)^{a+b+c}$ が成り立つことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $p\geqq1$，$t>0$ に対して，不等式 $t^p\geqq1+p(t-1)$ が成り立つことを示せ．
  \item $x>0$，$y>0$ と $0<q<1$ に対して，不等式 $qx+(1-q)y\geqq x^qy^{1-q}$ が成り立つことを示せ．
  \item $x>0$，$y>0$ に対して，不等式 $2x^3+y^3\geqq3x^2y$ が成り立つことを示せ．
\end{enumerate}

次の問いに答えよ．
\begin{enumerate}
  \item $a>0$，$a\neq1$ とする．このとき $x>0$ で定義された関数 $f(x)=(1+a^x)^{\frac1x}$ は減少関数であることを示せ．
  \item 次の4つの数の中から最小の数と最大の数を選べ．
  \[
  (3^{10}+4^{10})^{\frac1{10}},\quad(3^{11}+4^{11})^{\frac1{11}},\quad\left(3^{\frac1{10}}+4^{\frac1{10}}\right)^{10},\quad\left(3^{\frac1{11}}+4^{\frac1{11}}\right)^{11}
  \]
  \item $p_1,\dots,p_n$ を正の数とするとき，$\displaystyle\lim_{x\to\infty}(p_1^x+\dots+p_n^x)^{\frac1x}$ を求めよ．
\end{enumerate}

次の問いに答えよ．
\begin{enumerate}
  \item 関数 $g(x)=\dfrac{x-\sin x}{x^3}$ について，次の問いに答えよ．\\
  (i) $\displaystyle\lim_{x\to0}g(x)$ を求めよ．ただし $\displaystyle\lim_{x\to0}\frac{1-\cos x}{x^2}=\frac12$ は用いてよい．\\
  (ii) 区間 $0<x<\pi$ で $g(x)$ は減少することを示せ．
  \item 三角形ABCにおいて，$\angle$A，$\angle$B の大きさをそれぞれ $\alpha,\beta$ とする．$0<\alpha<\beta<\pi$ のとき，次の不等式が成り立つことを証明せよ．
  \[
  1<\frac{\beta-\sin\beta}{\alpha-\sin\alpha}<\frac{\beta^3}{\alpha^3}
  \]
\end{enumerate}

曲線 $y=\log x$ 上を動く点Pの時刻 $t$ における座標を $(x(t),y(t))$ と表し，Pの速度ベクトルと加速度ベクトルをそれぞれ $\vec v=\left(\dfrac{dx}{dt},\dfrac{dy}{dt}\right)$ と $\vec\alpha=\left(\dfrac{d^2x}{dt^2},\dfrac{d^2y}{dt^2}\right)$ とする．すべての時刻 $t$ で $|\vec v|=1$ かつ $\dfrac{dx}{dt}>0$ であるとして，次の問いに答えよ．
\begin{enumerate}
  \item Pが点 $(s,\log s)$ を通過する時刻における速度ベクトル $\vec v$ を $s$ を用いて表せ．
  \item Pが点 $(s,\log s)$ を通過する時刻における加速度ベクトル $\vec\alpha$ を $s$ を用いて表せ．
  \item Pが曲線全体を動くとき，$|\vec\alpha|$ の最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての実数で微分可能な関数 $f(x)$ がつねに $f'(x)=0$ をみたすとする．このとき $f(x)$ は定数であることを示せ．
  \item 実数全体で定義された関数 $g(x)$ が次の条件 $(*)$ をみたすならば，$g(x)=x+(\text{定数})$ であることを示せ．\\
  $(*)$ 正の定数 $C$ が存在して，すべての実数 $x,y$ に対して $|g(x)-g(y)-(x-y)|\leqq C|x-y|^2$ が成り立つ．
\end{enumerate}

曲線 $C:y=x^3-x$ 上の点 $\mathrm P(a,a^3-a)$（$a>0$）における接線を $l$ とし，$l$ が再び $C$ と交わる点をQとする．Qにおける $C$ の接線を $m$ とし，$l$ と $m$ のなす角を $\theta$（$0<\theta<\frac\pi2$）とする．
\begin{enumerate}
  \item Qの $x$ 座標を求め，$\tan\theta$ を $a$ で表せ．
  \item $\theta$ を最大にする $a^2$ の値と，そのときの $\tan\theta$ を求めよ．
\end{enumerate}

$g_n(x)=1+x+\dfrac{x^2}{2!}+\dots+\dfrac{x^n}{n!}$（$n=1,2,\dots$）とする．
\begin{enumerate}
  \item $n$ が偶数のとき $g_n(x)>0$（すべての $x$），$n$ が奇数のとき $g_n(x)=0$ はただ1つの実数解をもつことを，同時に帰納法で示せ．
  \item $n=3$ の実数解 $x_3$ は $-2<x_3<-1$ にあることを示せ．
  \item $n=5$ の実数解 $x_5$ について $x_5<x_3$ を示せ．
\end{enumerate}

曲線 $y=\dfrac2x$（$x>0$）上の点P$\left(p,\dfrac2p\right)$ における接線 $l$ と $x$ 軸，$y$ 軸の交点をA，Bとし，原点Oから $l$ に下ろした垂線の足をQとする．次を示せ．
\begin{enumerate}
  \item PはABの中点であり，三角形OABの面積は一定である．
  \item 2直線OP，OQは直線 $y=x$ に関して対称である．
  \item 積 OP$\cdot$OQ は一定である．その値を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}9+\dfrac{y^2}4=1$ の第1象限の点における接線が，$x$ 軸，$y$ 軸の正の部分と交わる点をA，Bとする．
\begin{enumerate}
  \item 線分ABの長さの最小値を求めよ．
  \item OA$+$OB の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $y=\dfrac x{x^2+4x+3}$ の漸近線，極値を求め，概形を描け．
  \item 曲線 $x=\dfrac{1+t^2}{1-t^2}$，$y=\dfrac{2t}{1-t^2}$（$t\neq\pm1$）の $x,y$ の関係式を求め，曲線上にない点を答えよ．
\end{enumerate}

$f(x)=\dfrac{x-\sin x}{x^2}$（$x\neq0$），$f(0)=a$ とする．
\begin{enumerate}
  \item $f$ が連続となる $a$ を求めよ．
  \item (1) のとき $f'(0)$ を定義にしたがって求めよ．
  \item $f$ は $-\pi\leqq x\leqq\pi$ で増加関数であることを示せ．
\end{enumerate}

$f(x)=1+\dfrac13\sin x$ とする．
\begin{enumerate}
  \item 方程式 $f(x)=x$ はただ1つの実数解 $\alpha$ をもち，$1<\alpha<\frac43$ であることを示せ．
  \item 任意の実数 $x,y$ に対して $|f(x)-f(y)|\leqq\frac13|x-y|$ を示せ．
  \item $a_0=0$，$a_n=f(a_{n-1})$ で定めた数列は $\alpha$ に収束することを示し，$|a_n-\alpha|<10^{-3}$ となる $n$ を1つ求めよ．
\end{enumerate}

2曲線 $C_1:y=\sin x$，$C_2:y=\dfrac1{\tan x}$（$0<x<\frac\pi2$）がある．
\begin{enumerate}
  \item 交点Pの $x$ 座標を $x_0$ とするとき，$\cos x_0$ の値を求めよ．
  \item Pにおける $C_1$ の接線と $C_2$ の接線は直交することを示せ．
  \item Pにおける2本の接線と $x$ 軸で囲まれる三角形の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $f''(x)$ が存在するとき，$f(b)=f(a)+f'(a)(b-a)+\frac12f''(c)(b-a)^2$ となる $c$（$a$ と $b$ の間）が存在することを示せ．
  \item $f''(x)>0$ の区間内の $x_1,\dots,x_n$ に対して $\frac1n\sum f(x_i)\geqq f\left(\frac1n\sum x_i\right)$ を示せ（等号は全部等しいとき）．
  \item 正の数 $x_1,\dots,x_n$ について $(x_1+\dots+x_n)\left(\dfrac1{x_1}+\dots+\dfrac1{x_n}\right)\geqq n^2$ を (2) から導け．
\end{enumerate}

曲線 $C_1:y=e^x$ 上の点Pと曲線 $C_2:y=\log x$ 上の点Qは，P，Qにおける接線が平行であるように動く．
\begin{enumerate}
  \item P$(p,e^p)$ のとき，Qの座標を $p$ で表せ．
  \item PQ が最小となるとき，直線PQはPにおける $C_1$ の接線と直交することを示し，PQの最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ と自然数 $n$ に対し，$g_n(x)=\displaystyle\sum_{k=0}^n\frac{(-x)^k}{k!}$ とおく．$\left|e^{-x}-g_n(x)\right|<\dfrac{x^{n+1}}{(n+1)!}$ を示せ．
  \item $\frac1e$ が有理数 $\frac mn$（$m,n$ は自然数）であると仮定して，$n!\left(e^{-1}-g_n(1)\right)$ を考えることで矛盾を導け．
\end{enumerate}

関数 $f(x)$ は微分可能で，(i) $f(x)\geqq1+2x$，(ii) すべての実数 $x,h$ に対して $f(x+h)\geqq f(x)f(h)$ をみたしている．
\begin{enumerate}
  \item $f(0)$ と $f'(0)$ を求めよ．
  \item $f(x)>0$ を示し，$f'(x)=2f(x)$ を示して $f(x)$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)=x^{-4}4^x$（$x\neq0$）について，$f'(x)>0$ となる $x$ の範囲を求めよ．
  \item 方程式 $4^x=x^4$ は相異なる3個の実数解をもつことを示せ．
  \item 方程式 $4^x=x^4$ の解で有理数であるものをすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての $t>0$ に対して $e^{\frac t2}-e^{-\frac t2}\geqq t$ を示せ．
  \item $a>0$ とする．すべての $t>0$ に対して $\dfrac{1-e^{-t}}t\geqq e^{-\frac ta}$ が成り立つような $a$ の範囲を求めよ．
\end{enumerate}

実数 $a$ に対して，曲線 $y=\sqrt x$ と直線 $y=a(x+1)+1$ を考える．
\begin{enumerate}
  \item 曲線と直線が共有点をもつような $a$ の範囲を求めよ．
  \item $0<a\leqq2$ とし，$u$ の2次方程式 $au^2-u+a+1=0$ の複素数の範囲での2解を $\alpha,\beta$（$|\alpha|\leqq|\beta|$）とする．$|\beta|$ の最小値を求めよ．
\end{enumerate}

関数 $f(x)=\dfrac{ax+b}{x+c}$ が次の条件 (A)，(B) をみたすとき，$a,b,c$ を求めよ．
\begin{itemize}
  \item[(A)] 曲線 $y=f(x)$ は直線 $y=x-1$ と2点で交わり，2交点の $x$ 座標は絶対値が等しく符号が異なる．
  \item[(B)] 曲線 $y=f(x)$ と $x$ 軸，$y$ 軸の交点はともに直線 $y=-2x+4$ 上にある．
\end{itemize}

\begin{enumerate}
  \item 方程式 $x+1=\sqrt{2x^2+4x+a}$ が実数解をもつための $a$ の条件と，そのときの解を求めよ．
  \item 不等式 $\sqrt{x+1}>ax+b$ の解が $-1\leqq x<3$ となるような正の数 $a,b$ について，$a+b$ のとり得る値の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $y=\dfrac{2^x-2^{-x}}2$（$x$ は実数全体）の逆関数を求めよ．
  \item (1) の逆関数を $g(x)$ とするとき，$g(x)=1$ となる $x$ と，$g\left(\frac{15}8\right)$ を求めよ．
\end{enumerate}

$f(x)=x^4+ax^3+bx^2+cx+d$ のグラフが $y$ 軸に平行な直線に関して対称であるとする．
\begin{enumerate}
  \item $a,b,c$ のみたす関係式を求めよ．
  \item $a=-8$，$b=18$ のとき $c$ を求め，$f(x)=g(h(x))$ となる2次関数 $g$，$h$ を1組求めよ．
  \item (2) で $d=0$ のとき，$f(x)$ の最小値を求めよ．
\end{enumerate}

$-1<x<1$ で定義された $f_p(x)=\dfrac{x-p}{1-px}$（$-1<p<1$）を考える．
\begin{enumerate}
  \item $-1<x<1$ ならば $-1<f_q(x)<1$ を示せ．
  \item $f_p(f_q(x))=f_r(x)$ となる $r$ を $p,q$ で表し，$-1<r<1$ を示せ．
  \item すべての $x$ で $f_p(f_p(x))=f_{\frac12}(x)$ となる $p$ を求めよ．
\end{enumerate}

$f_1(x)=x$，$f_2(x)=\dfrac1x$，$f_3(x)=1-x$，$f_4(x)=\dfrac1{1-x}$，$f_5(x)=\dfrac x{x-1}$，$f_6(x)=\dfrac{x-1}x$ とする（$x\neq0,1$）．以下 $a,b,k$ は $1,\dots,6$ のいずれか．
\begin{enumerate}
  \item $f_k(f_k(x))=f_1(x)$ となる $k$ をすべて求めよ．
  \item $f_3(f_a(x))=f_6(x)$ となる $a$，$f_b(f_4(x))=f_2(x)$ となる $b$ を求めよ．
  \item $f_4$ の逆関数は6つのうちのどれか．
\end{enumerate}

$f(x)=\sqrt x$（$x\geqq0$）の逆関数を $g(x)$ とする．$y\leqq f(x)$，$y\geqq g(x)$ を同時にみたす点 $(x,y)$ の集合を $M$ とし，$F(x,y)=ay+bx$ の $M$ 上の最小値を考える．
\begin{enumerate}
  \item $g(x)$ と $M$ を求めよ．
  \item $a=0$ のとき，$F$ の最小値を $b$ の符号で分けて求めよ．
  \item $a>0$ のとき，$F$ が $0<x<1$ の点で最小となるための $\frac ba$ の条件と，その最小値を求めよ．$a=4$，$b=-3$ のときの最小値を答えよ．
\end{enumerate}

$f(x)=\dfrac{2x}{1+x}$ とする．
\begin{enumerate}
  \item 実数 $t$ が $f(f(t))=f(t)$ をみたすとき，$f(t)=t$ も成り立つことを示し，そのような $t$ を求めよ．
  \item 不等式 $f(f(x))\geqq f(x)$ を解け．
\end{enumerate}

$n$ を2以上の自然数とする．
\begin{enumerate}
  \item 整式 $g(x)$ が $(x+1)^2$ で割り切れるための条件は $g(-1)=g'(-1)=0$ であることを示せ．
  \item $g(x)=ax^{n+1}+bx^n+1$ が $(x+1)^2$ で割り切れるとき，$a,b$ を $n$ で表せ．
\end{enumerate}

$f(x)$ はすべての実数で微分可能で，$f(2x)=(e^x+e^{-x})f(x)$ をみたす．$s(x)=\dfrac{e^x-e^{-x}}2$ とする．
\begin{enumerate}
  \item $f(0)=0$ を示せ．
  \item $x\neq0$ に対して $\dfrac{f(x)}{s(x)}=\dfrac{f(\frac x2)}{s(\frac x2)}$ を示せ．
  \item $f(x)=f'(0)s(x)$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item $y=\tan x$（$-\frac\pi2<x<\frac\pi2$）の逆関数を $y=f(x)$ とするとき，$f'(x)$ を求めよ．
  \item $g(x)=\dfrac{e^x+e^{-x}}2$（$x\geqq0$）の逆関数を $h(x)$（$x\geqq1$）とする．$x>1$ で $h'(x)$ を求め，$(x^2-1)h'''(x)+3xh''(x)$ を $h'(x)$ で表せ．
\end{enumerate}

$x\geqq0$ で定義された $f(x)=xe^{x^2}$ の逆関数を $g(x)$ とする．
\begin{enumerate}
  \item $f'(1)$，$f''(1)$ を求めよ．
  \item $g'(e)$，$g''(e)$ を求めよ．
\end{enumerate}

$n$ 次の整式 $T_n(x)$ は $T_n(\cos\theta)=\cos n\theta$ をみたす（$n=1,2,\dots$）．
\begin{enumerate}
  \item $T_n'(\cos\theta)=\dfrac{n\sin n\theta}{\sin\theta}$（$\sin\theta\neq0$）を示し，$T_n'(1)$ を求めよ．
  \item $T_n''(\cos\theta)$ を $\theta$ で表し，$T_n''(1)=\dfrac{n^2(n^2-1)}3$ を示せ．
\end{enumerate}

微分可能な関数 $f(x)$ が任意の実数 $x,y$ で $f(x+y)=f(x)\sqrt{1+f(y)^2}+f(y)\sqrt{1+f(x)^2}$ をみたす．
\begin{enumerate}
  \item $f(0)$ を求め，$f(-x)=-f(x)$ を示せ．
  \item $f'(0)=2$ のとき，$f'(x)$ を $f(x)$ で表せ．
  \item (2) のとき $f(x)$ を求めよ．
\end{enumerate}

$c>1$ とし，$f(x)$ は微分可能ですべての $x$ で $f'(x)\geqq c$ をみたす．
\begin{enumerate}
  \item $x\geqq0$ で $f(x)-f(0)\geqq cx$，$x\leqq0$ で $f(x)-f(0)\leqq cx$ を示せ．
  \item 方程式 $f(x)=x$ はただ1つの実数解をもつことを示せ．
\end{enumerate}

$f(x)=\dfrac x2\left\{1+e^{-3(x-1)}\right\}$ とする．
\begin{enumerate}
  \item $x>\frac13$ ならば $|f'(x)|\leqq\dfrac{e-1}2$ であることを示せ．
  \item $x>\frac13$ ならば $f(x)>\frac13$ であることを示せ．
  \item $x_0>\frac13$，$x_{n+1}=f(x_n)$ のとき $\displaystyle\lim_{n\to\infty}x_n=1$ を示せ．
\end{enumerate}

$f(x)=\dfrac1{1+x^2}$ を $x>0$ で考える．点 $(a,f(a))$ における接線を $l_a$，その $y$ 切片を $Y(a)$ とする．
\begin{enumerate}
  \item $Y(a)$ のとり得る値の範囲を求めよ．
  \item $0<a<b$ で $l_a$ と $l_b$ が $x$ 軸上で交わるとき，$a$ の範囲を求め，$b$ を $a$ で表せ．
  \item (2) のとき $Z(a)=Y(a)-Y(b)$ とする．$\displaystyle\lim_{a\to+0}Z(a)$ と $\displaystyle\lim_{a\to+0}\frac{Z'(a)}a$ を求めよ．
\end{enumerate}

$n$ を正の整数とする．
\begin{enumerate}
  \item 正の整数 $k$ に対して $(1-x)^nx^k$ の $0\leqq x\leqq1$ での最大値 $a_n$ を求め，$\displaystyle\lim_{n\to\infty}n^ka_n$ を求めよ．
  \item $p\geqq0$，$q>0$ とし，$(1-x)^n(px^2+qx)$ の $0\leqq x\leqq1$ での最大値を $e_n$ とする．$\displaystyle\lim_{n\to\infty}ne_n$ を求めよ．
\end{enumerate}

平面上を半径1の3つの円板が，(a) 中心はいずれも定点Pを中心とする半径1の円周上にある，(b) 3つすべてが共有する点はPのみである，をみたしながら動く．Pから見た隣り合う中心の間の角を $\alpha_1,\alpha_2,\alpha_3$（和 $2\pi$）とする．
\begin{enumerate}
  \item 中心間の角が $\varphi$（$0\leqq\varphi\leqq\pi$）の2つの円板の共通部分の面積は $\pi-\varphi-\sin\varphi$ であることを示せ．
  \item (b) より $\alpha_i\leqq\pi$ であることを用いて，3つの円板の和集合の面積を $\alpha_i$ で表せ．
  \item $\alpha_1=\frac\pi2$ のとき，和集合の面積の最大値を求めよ．
\end{enumerate}

A$(-1,0)$，B$(1,0)$ からの距離の積が $\frac32$ である点の軌跡を $C$ とする．
\begin{enumerate}
  \item $C$ の方程式を求め，$x$ 軸，$y$ 軸に関して対称であることを示せ．
  \item $C$ と $x$ 軸，$y$ 軸の交点を求めよ．
  \item $C$ 上の点の $y$ 座標の最大値と，そのときの $x$ を求め，$C$ の概形の特徴を述べよ．
\end{enumerate}

\begin{enumerate}
  \item $t>0$ で定義された $f(t)=e^{-t}\cos t$ が極値をとる $t$ を小さい順に $t_1,t_2,\dots$ とする．$t_n$ と $f(t_n)$ を求めよ．
  \item 曲線 $C:x=e^t\cos t$，$y=e^t\sin t$（$t>0$）と点 P$(r,0)$（$r>0$）がある．$C$ の接線で P を通るものの本数を $N(r)$ とする．$N(r)=1$ となる $r$ の範囲，$N(r)=2$ となる $r$ の値，$N(r)=3$ となる $r$ の範囲を求めよ．
\end{enumerate}

$k$ を正の整数とし，$(2k-1)\pi\leqq x\leqq2k\pi$ で2曲線 $C_1:y=\cos x$，$C_2:y=\dfrac{x^2-1}{x^2+1}$ を考える．
\begin{enumerate}
  \item $C_1$ と $C_2$ は共有点をもち，その点における $C_1$ の接線は点 $(0,-1)$ を通ることを示せ．
  \item $C_1$ と $C_2$ の共有点はただ1つであることを示せ．
\end{enumerate}

曲線 $C:y=\dfrac{e^x+e^{-x}}2$ の上を，速さ1で $x$ 成分が正となるように点 P が動く．点 Q を P における $C$ の法線上にあり PQ$=1$ で，領域 $y<\dfrac{e^x+e^{-x}}2$ にある点とする．
\begin{enumerate}
  \item P$\left(u,\frac{e^u+e^{-u}}2\right)$ のとき，Q の座標を求めよ．
  \item Q の速さのとり得る値の範囲を求めよ．
\end{enumerate}

点 P$(0,1)$ を中心とする半径1の円を $C$ とする．$a>0$ とし，直線 $y=a(x+1)$ と $C$ の2つの交点を Q，R とする．
\begin{enumerate}
  \item $\triangle$OQR の面積 $S(a)$ を求めよ（O は原点）．
  \item $S(a)$ が最大となる $a$ と最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $t>0$ のとき $\dfrac{2t}{2+t}<\log(1+t)<t$ を示せ．
  \item $x>0$ のとき $\left(1+\dfrac1x\right)^x<e<\left(1+\dfrac1x\right)^{x+\frac12}$ を示せ．
  \item 「すべての $x>0$ に対して $\left(1+\dfrac1x\right)^{x+c}>e$」が成り立つような定数 $c$ の最小値を求めよ．
\end{enumerate}

$x>1$ で $f(x)=\dfrac{(x+1)\log x}{x-1}$ とする．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to1+0}f(x)$ を求めよ．
  \item $f(x)$ は $x>1$ で単調に増加することを示せ．
  \item $x>1$ のとき $\log x>\dfrac{2(x-1)}{x+1}$ を示せ．
\end{enumerate}

$y=\log\dfrac{\sqrt{x+5}-\sqrt x}{\sqrt{x+5}+\sqrt x}$（$x>0$）とする．
\begin{enumerate}
  \item $\dfrac{dy}{dx}$ を求め，できるだけ簡単な形で表せ．
  \item 曲線の $x=4$ における接線の方程式を求めよ．
  \item $\displaystyle\int_4^{20}\frac{dx}{\sqrt{x(x+5)}}$ を求めよ．
\end{enumerate}

$f(x)=\dfrac x{x^2-2x+4}$，$g(x)=\dfrac{x^2}{x^2-2x+4}$ とする．
\begin{enumerate}
  \item $f(x)$ の最大値と最小値を求めよ．
  \item $g(x)$ の最大値と最小値を求めよ．
  \item $f(x)+g(x)=\dfrac{x^2+x}{x^2-2x+4}$ の最大値は，(1)(2) の最大値の和より小さいことを示し，実際の最大値を求めよ．
\end{enumerate}

$xy$ 平面上の曲線 $y=x^2$ を $y$ 軸のまわりに1回転してできる曲面を $S$ とする．
\begin{enumerate}
  \item 点 $\mathrm A\left(2\sqrt3,-\frac12,2\right)$ から $S$ にいたる最短距離と，最短距離を与える $S$ 上の点の座標を求めよ．
  \item $b>0$ とする．点 $(0,b,0)$ から $S$ にいたる最短距離を $b$ で表し，最短距離を与える $S$ 上の点全体がどのような図形になるかを答えよ．
\end{enumerate}

$n$ を自然数とし，$g(x)=\displaystyle\sum_{k=1}^n\frac{x^{k+2}}{k(k+1)(k+2)}$ とする．
\begin{enumerate}
  \item $-1\leqq x\leqq1$ で $g'''(x)\geqq0$ を示せ．
  \item $g(x)$ は $-1\leqq x\leqq1$ で増加することを示せ．
  \item $-1\leqq x\leqq1$ において $-\dfrac16\leqq g(x)<\dfrac14$ が成り立つことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $a>0$ とする．曲線 $C_1:y^2=x(x-a)^2$ は $0\leqq x\leqq a$ の部分でループをつくる．ループ上で $|y|$ が最大となる点，点 $(a,0)$ における2本の接線の傾き，およびループで囲まれる部分の面積を求めよ．
  \item 曲線 $C_2:x=t+\dfrac1{t^2}$，$y=t^2+\dfrac2t$（$t>0$）について，接線が $y$ 軸に平行になる点と $x$ 軸に平行になる点を求めよ．また $\displaystyle\lim_{t\to+0}\frac{y^2}x$ と $\displaystyle\lim_{t\to\infty}\frac y{x^2}$ を求めよ．
  \item 極方程式 $r=1+2\cos\theta$（$0\leqq\theta<2\pi$）で表される曲線の内側のループで囲まれる部分の面積を求めよ．
\end{enumerate}

方程式 $x^3+x-1=0$ の実数解を $\alpha$ とする．正の定数 $\lambda$ に対して $g(x)=x-\lambda(x^3+x-1)$ とおき，$a_1\in[0,1]$，$a_{n+1}=g(a_n)$ で数列を定める．
\begin{enumerate}
  \item $0<\alpha<1$ であり，$\alpha$ がただ1つの実数解であることを示せ．
  \item $0\leqq x\leqq1$ における $|g'(x)|$ の最大値 $k(\lambda)$ を求め，$k(\lambda)$ を最小にする $\lambda$ とその最小値を求めよ．
  \item (2) の $\lambda$ に対して，$g$ は区間 $[0,1]$ をそれ自身に移すことを示し，$|a_n-\alpha|\leqq\left(\dfrac35\right)^{n-1}$ を示せ．
\end{enumerate}

$f(x)$ は微分可能で，つねに $f(x)>0$ かつ $f'(x)\leqq-\{f(x)\}^2$ をみたすとする．
\begin{enumerate}
  \item $f$ が $x>0$ で定義され $f(1)=1$ のとき，$x\geqq1$ で $f(x)\leqq\dfrac1x$ を示し，$\displaystyle\lim_{x\to\infty}f(x)$ を求めよ．また，$0<x<1$ で $f(x)\geqq\dfrac1x$ を示せ．
  \item このような $f$ で，実数全体で定義されたものは存在しないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(t)=\dfrac{\log t}t$（$t>0$）の増減と極限を調べ，グラフの概形を描け．
  \item 正の数 $x<y$ が $x^y=y^x$ をみたすとき，$x<e<y$，$xy>e^2$，$x+y>2e$ を示せ．
  \item $x\neq y$ である正の整数の組で $x^{2y}=y^x$ をみたすものをすべて求めよ．
\end{enumerate}

$0<a<\frac1e$ である $a$ に対して $xe^{-x}=a$ をみたす $x$ は2つある．小さい方を $u$，大きい方を $v$ とする．
\begin{enumerate}
  \item $\dfrac{du}{da}$，$\dfrac{dv}{da}$ を $u,v$ で表せ．
  \item $r=\dfrac vu$ とおくとき，$u,v$ を $r$ で表し，$u+v>2$ を示せ．
  \item $uv$ のとり得る値の範囲を求めよ．
\end{enumerate}

1辺の長さ2の正三角形ABCで，Aから辺BCに下ろした垂線をAHとする．線分AH上（両端を除く）に中心Oをもつ半径1の円 $C$ を考え，三角形の3つの辺（線分）がいずれも，辺の両端以外の異なる2点で $C$ の周と交わるとき $\mathrm{AO}=x$ とおく．三角形ABCと円 $C$ の内部の共通部分の面積を $S$ とし，$F(t)=2\displaystyle\int_t^1\sqrt{1-u^2}\,du$（$0\leqq t\leqq1$）とする．
\begin{enumerate}
  \item $x$ のとり得る値の範囲を求めよ．
  \item $S$ を $F$ を用いて表せ．
  \item $S$ を最大にする $x$ と，$S$ の最大値を求めよ．
\end{enumerate}

面積が1の正 $n$ 角形（$n\geqq3$）の周の長さを $L_n$ とする．
\begin{enumerate}
  \item $L_n$ を求めよ．
  \item $3\leqq n<m$ のとき $L_n>L_m$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}L_n$ と $\displaystyle\lim_{n\to\infty}n^2(L_n-\lim_{m\to\infty}L_m)$ を求めよ．
\end{enumerate}

$f(x)=x^2\left(2+\sin\dfrac1x\right)$（$x\neq0$），$f(0)=0$ とする．
\begin{enumerate}
  \item $f$ は $x=0$ で微分可能であることを示し，$f'(0)$ を求めよ．
  \item $f$ は $x=0$ で最小値をとることを示せ．
  \item どんな $\delta>0$ に対しても，$f$ は区間 $(0,\delta)$ で単調増加ではないことを示せ．
\end{enumerate}

$a>0$ とし，曲線 $C_1:y=ax\sin x$，$C_2:y=\cos x$ を考える．
\begin{enumerate}
  \item $C_1$ と $C_2$ は無数に多くの交点をもつことを示せ．
  \item $C_1,C_2$ のすべての交点で2曲線の接線が直交するための $a$ の条件を求めよ．また，その条件をみたさない $a$ では，どの交点でも接線は直交しないことを示せ．
\end{enumerate}

放物線 $C:y=\dfrac{x^2}4$ の焦点を F$(0,1)$ とする．$C$ 上を動く点Pの時刻 $t$ における座標を $(x(t),y(t))$ とし，$x(0)=0$，$x(t)\geqq0$ とする．線分OF，FPと弧OPで囲まれた部分の面積 $S(t)$ がつねに $\dfrac{dS}{dt}=\dfrac12$ をみたすとき，
\begin{enumerate}
  \item $\dfrac{dx}{dt}$ を $x$ で表し，PF の長さを $x$ で表せ．
  \item 加速度ベクトル $\vec\alpha$ は $\overrightarrow{\mathrm{PF}}$ と同じ向きであることを示し，$|\vec\alpha|\cdot\mathrm{PF}^2$ の値を求めよ．
\end{enumerate}

$f(x)$ は2回微分可能とし，曲線 $C:y=f(x)$ 上の点 P$(p,f(p))$ における法線を $l_{\mathrm P}$，$C$ 上の P と異なる点 Q$(q,f(q))$ における法線を $l_{\mathrm Q}$ とする．$l_{\mathrm P}$ と $l_{\mathrm Q}$ の交点をRとし，Q が P に近づくときに R が近づく点を T とする（$f''(p)\neq0$）．
\begin{enumerate}
  \item T の座標と線分PTの長さを $p,f(p),f'(p),f''(p)$ で表せ．
  \item $f(x)=\dfrac1x$（$x>0$）とし，P が $C$ 上を動くとき，PT の最小値とそのときの T の座標を求めよ．
\end{enumerate}

$a$ を正の定数とする．第1象限にある曲線 $C:y=f(x)$ は2回微分可能で $f''(x)>0$ をみたし，$C$ 上の任意の点における接線は $x$ 軸，$y$ 軸の正の部分とそれぞれ P，Q で交わり，つねに $\mathrm{OP}+\mathrm{OQ}=a$ が成り立つ（O は原点）．
\begin{enumerate}
  \item $f(x)$ を求めよ（定義域も答えよ）．
  \item $x$ 切片 $p$，$y$ 切片 $a-p$（$0<p<a$）の線分全体が通過する範囲は，$x>0$，$y>0$，$\sqrt x+\sqrt y\leqq\sqrt a$ であることを示せ．
  \item (2) の範囲の面積を求めよ．
\end{enumerate}

$c>0$ とし，$x>0$ の範囲で方程式 $e^x=cx^2$ を考える．$\displaystyle\lim_{x\to\infty}\frac{e^x}{x^2}=\infty$ は証明なしに使ってよい．
\begin{enumerate}
  \item $x>0$ の範囲に異なる2つの解をもつような $c$ の範囲を求めよ．
  \item $c$ が (1) の範囲にあるとき，2つの解を $\alpha<\beta$ とする．$0<\alpha<2<\beta$ と $\alpha\beta<4$ を示せ．
  \item 同じく $\alpha+\beta>4$ を示せ．
\end{enumerate}

(I) $a$ を実数とし，$f(x)=|x|(e^{3x}+a)$ が $x=0$ で微分可能であるとする．
\begin{enumerate}
  \item $a$ および $f'(0)$ の値を求めよ．
  \item 導関数 $f'(x)$ は $x=0$ で連続であることを示せ．
  \item 右側極限 $\displaystyle\lim_{x\to+0}\frac{f'(x)}x$ と左側極限 $\displaystyle\lim_{x\to-0}\frac{f'(x)}x$ を求め，$f'(x)$ は $x=0$ で微分可能でないことを示せ．
\end{enumerate}
(II) $f(x)$ はすべての実数で微分可能で，$f(3x)=(e^{2x}+e^x+1)f(x)$ をみたす．
\begin{enumerate}
  \item $f(0)=0$ を示せ．
  \item $x\neq0$ に対して $\dfrac{f(x)}{e^x-1}=\dfrac{f(x/3)}{e^{x/3}-1}$ を示せ．
  \item $f(x)=(e^x-1)f'(0)$ を示せ．
\end{enumerate}

$x\geqq0$ で定義された関数 $f(x)=xe^{\frac x3}$ の逆関数を $g(x)$ とする．
\begin{enumerate}
  \item $f'(3)$，$f''(3)$ を求めよ．
  \item $g'(3e)$，$g''(3e)$ を求めよ．
  \item 曲線 $y=g(x)$ は $x>0$ で上に凸であることを示せ．
\end{enumerate}

$f(x)=\dfrac{x^3+x^2}{x^2-2}$ とする．
\begin{enumerate}
  \item $f(x)$ の増減を調べ，極値を求めよ．
  \item 曲線 $y=f(x)$ の漸近線を求めよ．
  \item 曲線 $y=f(x)$ の概形を描け．
\end{enumerate}

$f(x)=\dfrac{x+3}{\sqrt{x+1}}$（$x>-1$）とする．$y$ 軸上の点 $\mathrm A(0,b)$ から曲線 $y=f(x)$ に引ける接線の本数を考える．
\begin{enumerate}
  \item 接点の $x$ 座標を $t$ とするとき，$b=B(t)$ と表せ．
  \item 曲線 $y=f(x)$ のどの接線も，曲線と2点で接することはないことを示せ．
  \item 異なる接線がちょうど2本引けるような $b$ の値をすべて求めよ．また，ちょうど3本引ける $b$ の範囲を求めよ．
\end{enumerate}

$xy$ 平面上に曲線 $C:y=\dfrac{x^2}2$ がある．$C$ 上にない点 $\mathrm A(X,Y)$ と $C$ 上の点 P に対し，P における $C$ の接線と直線 AP が垂直であるとき，線分 AP を A から $C$ に下ろした垂線という．
\begin{enumerate}
  \item $C$ に異なる3本の垂線を下ろせる点 A の範囲を求め，図示せよ．
  \item A が (1) の範囲にあるとき，3本の垂線の足を頂点とする三角形の重心の座標を $X,Y$ で表せ．
  \item A が $y$ 軸上にあり，3本の垂線の足が正三角形の頂点となるとき，A の座標を求めよ．
\end{enumerate}

定数 $a$ に対して，$xy$ 平面の曲線 $C_a:y=(x-a)^2\{1-\log(x-a)\}$（$x>a$）を考える．
\begin{enumerate}
  \item $a=0$ のときの曲線 $C_0$ の概形を，増減・凹凸・極限を調べてかけ．ただし $\displaystyle\lim_{x\to+0}x^2\log x=0$ を用いてよい．
  \item $a$ を $a\geqq0$ の範囲で動かすとき，曲線 $C_a$ が通る部分を図示せよ．
\end{enumerate}

連立不等式 $x^2+(y-1)^2\leqq1$，$x\geqq\dfrac{\sqrt3}6$ で定まる領域を $D$ とする．原点を通り $x$ 軸と角 $\theta$（$0<\theta<\frac\pi2$）をなす直線 $l$ と $D$ の共通部分が線分となるとき，その長さを $L$ とする．
\begin{enumerate}
  \item 共通部分が線分となるための $\theta$ の条件を $\sin2\theta$ で表せ．
  \item $L$ の最大値と，そのときの $\cos\theta$ を求めよ．
\end{enumerate}

平面上の定点 P を中心とする半径1の円周上に中心をもつ，半径1の円板を考える．
\begin{enumerate}
  \item 中心 $\mathrm O_1$，$\mathrm O_2$ をもつ2枚の円板について，$\angle\mathrm O_1\mathrm P\mathrm O_2=\varphi$（$0<\varphi\leqq\pi$）のとき，共通部分の面積は $\pi-\varphi-\sin\varphi$ であることを示せ．
  \item 4枚の円板の中心が長方形の4頂点をなすとき，4枚すべてに共通な点は P のみであることを示せ．さらに，隣り合う中心が P から見て角 $\varphi$ をなすとして，和集合の面積 $S(\varphi)$ を求め，その最大値を求めよ．
  \item 3枚の円板の中心が P から見て順に $90^\circ$，$90^\circ$，$180^\circ$ の角をなすように並ぶとき，和集合の面積を求めよ．
\end{enumerate}

関数 $f(x)=x^x$（$x>0$）と正の実数 $a$ について答えよ．
\begin{enumerate}
  \item $\dfrac12\leqq x\leqq\dfrac32$ における $f(x)f(2-x)$ の最大値と最小値を求めよ．
  \item $\dfrac12\leqq x\leqq\dfrac32$ における $\dfrac{f(x)f(2-x)f(a)^2}{f(ax)f(a(2-x))}$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $n\geqq2$，$p_1,\dots,p_n>0$，$0<\alpha<\beta$ のとき，$\left(\sum p_i^\alpha\right)^{\frac1\alpha}>\left(\sum p_i^\beta\right)^{\frac1\beta}$ を示せ．
  \item 次の4つの数のうち最大のものと最小のものを答えよ．
  \[(3^{10}+5^{10})^{\frac1{10}},\ (3^{11}+5^{11})^{\frac1{11}},\ (3^{\frac1{10}}+5^{\frac1{10}})^{10},\ (3^{\frac1{11}}+5^{\frac1{11}})^{11}\]
  \item $M_\alpha=\left(\frac1n\sum p_i^\alpha\right)^{\frac1\alpha}$ とおく．$0<\alpha<\beta$ のとき $M_\alpha\leqq M_\beta$ を示し，(1) と大小の向きが逆になる理由を説明せよ．
\end{enumerate}

$n$ を自然数とする．
\begin{enumerate}
  \item $x\geqq0$ のとき，$0\leqq e^{-x}-(1-x)\leqq\dfrac{x^2}2$ を示せ．
  \item $0\leqq x\leqq n$ のとき，$0\leqq e^{-x}-\left(1-\dfrac xn\right)^n\leqq\dfrac{x^2}{2n}$ を示せ．
  \item $\left|\left(1-\dfrac1n\right)^n-\dfrac1e\right|\leqq\dfrac1{2n}$ を示し，$\displaystyle\lim_{n\to\infty}\left(1-\frac1n\right)^n$ を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ の $y>0$ の部分を，点 P$(x,y)$ が速さ一定 $C$ で，$x$ が増加する向きに動く．
\begin{enumerate}
  \item P の速度ベクトル $\vec v=\left(\dfrac{dx}{dt},\dfrac{dy}{dt}\right)$ を $x$ で表せ．
  \item P の加速度ベクトル $\vec\alpha$ を $x$ で表し，その大きさを求めよ．
  \item 半径 $r$ の円周上を速さ $C$ で動く点の加速度の大きさは $\frac{C^2}r$ である．P が点 $(0,1)$ にあるときの加速度の大きさがこれと等しくなる $r$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac\pi4\leqq a<\dfrac\pi2$，$\dfrac\pi4\leqq b<\dfrac\pi2$ のとき，次を示せ．
  \[\tan\frac{a+b}2\leqq\sqrt{\tan a\tan b}\leqq\frac{\tan a+\tan b}2\]
  \item (1) の左側の等号が成り立つための条件を求めよ．
  \item $0<a<\dfrac\pi4<b<\dfrac\pi2$，$a+b=\dfrac\pi2$ のとき，$\tan\dfrac{a+b}2$ と $\sqrt{\tan a\tan b}$ の大小を答えよ．
\end{enumerate}

$f(x)=\log\dfrac{x^2+3}{6}$ とし，曲線 $D:y=f(x)$ のすべての変曲点で $D$ に接する円を $C$ とする．
\begin{enumerate}
  \item $D$ の変曲点と $C$ の方程式を求めよ．
  \item $C$ と $D$ の共有点は $D$ の変曲点のみであることを証明せよ．
  \item $C$ と $D$ で囲まれた部分の面積を求めよ．
\end{enumerate}

$f(x)=-\dfrac{e^x+e^{-x}}2$ とし，曲線 $C:y=f(x)$ を考える．1辺の長さ $a$ の正方形 QRST（辺QRの対辺がST）は，最初，辺QRの中点Mが $C$ 上の点 $(0,f(0))$ に一致し，QRが $C$ に接し，正方形が $y>f(x)$ の側にあるようにおかれている．ついで，正方形が曲線 $C$ に接しながらすべることなく右に傾いてゆく．辺STの中点をNとする．
\begin{enumerate}
  \item 接点の $x$ 座標が $x$ のとき，Nの座標を $x$ と $a$ で表せ．
  \item 最初の状態から点Rが初めて $C$ 上にくるまでの間，Nの $y$ 座標が一定であるような $a$ を求めよ．
  \item (2) のとき，Rが $C$ 上にきた瞬間のNの座標を求めよ．
\end{enumerate}

$x\geqq0$ で定義された微分可能な関数 $f(x)$ は，$f(0)=0$，$x>0$ で $f'(x)>0$ をみたす．また，曲線 $C:y=f(x)$ 上で原点から点 $(x,f(x))$ までの長さは $\displaystyle\int_0^xf(u)\,du+x$ に等しい．
\begin{enumerate}
  \item $f(x)$ を求めよ．
  \item $C$ 上を動く点 $\mathrm P(x(t),y(t))$ の速度ベクトル $\vec v(t)$ は $x'(t)\geqq0$，$|\vec v(t)|=t$ をみたし，$(x(0),y(0))=(0,0)$ である．$t=\dfrac{\sqrt6}2$ における $\vec v$ を求めよ．
\end{enumerate}

$a\geqq b>0$，$n$ を自然数とする．
\begin{enumerate}
  \item $a^n-b^n\leqq\dfrac n2(a-b)(a^{n-1}+b^{n-1})$ を，$b$ を固定し $a$ を変数とみる方法で示せ．
  \item $a^n-b^n\geqq n(a-b)\left(\dfrac{a+b}2\right)^{n-1}$ を示せ．
  \item (1)，(2) の不等式がともに等号となるのは，どのようなときか．
\end{enumerate}

\begin{enumerate}
  \item $t>1$ のとき，$\dfrac{2(t-1)}{t+1}<\log t<\dfrac{t-1}{\sqrt t}$ を示せ．
  \item $a>1$ とし，曲線 $C:y=\log x$ 上の2点 $\mathrm P(a,\log a)$，$\mathrm Q\left(\frac1a,-\log a\right)$ における接線の交点を R とする．R の座標を求め，R は領域 $0<x<1$，$y>0$ にあることを示せ．
  \item R の座標を $(X,Y)$ とするとき，$\displaystyle\lim_{a\to1+0}\frac{1-X}{(a-1)^2}$ と $\displaystyle\lim_{a\to1+0}\frac Y{(a-1)^2}$ を求めよ．
\end{enumerate}

曲線 $y=\sin x$ の $x=t$（$\frac\pi2<t<\pi$）における接線と，$x$ 軸，$y$ 軸で囲まれる三角形の面積を $S(t)$ とする．
\begin{enumerate}
  \item $S(t)$ を $t$ の式で表せ．
  \item $S(t)$ はある1点 $t=t_0$ で最小値をとることを示せ．また，$\dfrac{7}{12}\pi<t_0<\dfrac23\pi$ を示せ．
  \item $S(t_0)=2t_0\sin t_0$ を示せ．また，$S(t_0)>\dfrac{7\sqrt3}{12}\pi$ を示せ．
\end{enumerate}

$x>0$ に対し $f(x)=\dfrac{\log x}{x^2}$ とする．
\begin{enumerate}
  \item $n=0,1,2,\dots$ に対し $f^{(n)}(x)=\dfrac{a_n+b_n\log x}{x^{n+2}}$（$a_n,b_n$ は定数）と表されることを示し，$a_n,b_n$ の漸化式を求めよ．ただし $f^{(0)}=f$ とする．
  \item $h_m=\displaystyle\sum_{k=1}^m\frac1k$ とおく．$a_n,b_n$ を $n$ と $h_{n+1}$ を用いて表せ．
  \item $n\geqq1$ のとき，$f^{(n)}(x)=0$ をみたす $x$ はただ1つであることを示し，それを $x_n$ とする．数列 $\{x_n\}$ は増加し，$\displaystyle\lim_{n\to\infty}x_n=\infty$ であることを示せ．
\end{enumerate}

$t$ を $0<t<1$ をみたす実数とする．$0$，$\dfrac1t$ 以外のすべての実数 $x$ で定義された関数
\[
f(x)=\frac{x^2+t}{x(1-tx)}
\]
を考える．
\begin{enumerate}
  \item $f(x)$ は極大値と極小値を1つずつもつことを示せ．
  \item $f(x)$ の極大値を与える $x$ の値を $\alpha$，極小値を与える $x$ の値を $\beta$ とし，座標平面上に2点 $\mathrm P(\alpha,f(\alpha))$，$\mathrm Q(\beta,f(\beta))$ をとる．$t$ が $0<t<1$ の範囲で変化するとき，線分 PQ の中点 M の軌跡を求めよ．
\end{enumerate}

$x>0$ に対し $f(x)=1000\log\left(1+\dfrac1x\right)$ とおく．ただし対数は自然対数とする．また，実数 $a$ に対し，$a$ を超えない最大の整数を $[a]$ で表す．
\begin{enumerate}
  \item $x>0$ のとき，次の不等式を証明せよ．
  \[
  \frac{1000}{(x+1)^2}<f(x)-f(x+1)<\frac{1000}{x(x+2)}
  \]
  \item $u>0$ のとき，$\log(1+u)<\dfrac{u(2+u)}{2(1+u)}$ を示せ．
  \item 1000個の整数 $[f(1)],\ [f(2)],\ \dots,\ [f(1000)]$ のうちで異なるものの個数を求めよ．
\end{enumerate}

空間に2定点 P，O を距離 $\mathrm{PO}=1$ となるようにとり，O を中心とする半径 $r\ (0<r<1)$ の球面 $S$ を考える．P から $S$ に引いた接線の接点全体は1つの円 $C$ をなす．P を頂点とし $C$ を底面の周とする直円錐から，球面 $S$ で囲まれた球体との共通部分を除いた立体を $K$ とする．
\begin{enumerate}
  \item $K$ の体積 $V(r)$ を $r$ で表し，$V(r)$ の最大値とそのときの $r$ の値を求めよ．
  \item $K$ の表面積 $T(r)$ を $r$ で表し，$T(r)$ の最大値とそのときの $r$ の値を求めよ．ただし，半径 $r$ の球面のうち1つの平面で切り取られた高さ $h$ の部分（球冠）の面積が $2\pi rh$ であることは用いてよい．
\end{enumerate}

\begin{enumerate}
  \item すべての正の実数 $x,y$ に対して
  \[
  \sqrt[3]x+\sqrt[3]y\leqq k\sqrt[3]{x+8y}
  \]
  が成り立つような実数 $k$ の最小値を求めよ．
  \item すべての正の実数 $x,y$ に対して
  \[
  \sqrt[3]x+\sqrt[3]y\geqq m\sqrt[3]{x+8y}
  \]
  が成り立つような実数 $m$ の最大値を求めよ．
\end{enumerate}

$e$ を自然対数の底とする．
\begin{enumerate}
  \item $x>0$ のとき，$\left(1+x+\dfrac{x^2}2+\dfrac{x^3}6\right)e^{-x}<1$ を示せ．
  \item $0<x<4$ のとき，次の不等式を示せ．
  \[
  1+x+\frac{x^2}2+\frac{x^3}6<e^x<\frac{24+18x+6x^2+x^3}{6(4-x)}
  \]
  \item (2) を用いて，$e$ の値を小数第2位まで求めよ（小数第3位以下は切り捨てる）．
\end{enumerate}

$\alpha,\beta,\gamma$ は $\alpha>0$，$\beta>0$，$\gamma>0$，$\alpha+\beta+\gamma=\pi$ をみたすものとする．
\begin{enumerate}
  \item $\sin^2\alpha\sin\beta\sin\gamma$ の最大値を求めよ．
  \item $\sin\alpha+\sin\beta\sin\gamma$ の最大値を求めよ．
\end{enumerate}

$xy$ 平面において，曲線 $y=\dfrac{e^x+e^{-x}}2$ 上の点 $(0,1)$ を出発し，この曲線上を進む点 P がある．出発してから $t$ 秒後の P の位置を $(x,y)$ とするとき，そのときの P の速度 $\vec v$ の大きさは $y^2$ に等しく，$\vec v$ の $x$ 成分はつねに正であるとする．
\begin{enumerate}
  \item $x$ と $t$ の間の関係式を求めよ．また，P の $x$ 座標が限りなく大きくなるとき，$t$ はどんな値に近づくか．
  \item $y$ および $\vec v$ を $t$ で表し，$\vec v$ と $x$ 軸の正の向きとのなす角が $t$ に等しいことを示せ．
  \item $\vec v$ がベクトル $(8,15)$ と平行になるときの P の位置を求めよ．
\end{enumerate}

実数 $t>1$ に対し，$xy$ 平面上の点O$(0,0)$，P$(1,1)$，Q$\left(t,\dfrac1t\right)$ を考える．三角形OPQの面積を $a(t)$，線分OP，OQと双曲線 $xy=1$ とで囲まれた部分の面積を $b(t)$ とする．また，双曲線 $xy=1$ のPにおける接線とQにおける接線の交点をRとし，四角形OPRQの面積を $d(t)$ とする．
\begin{enumerate}
  \item Rの座標と $d(t)$ を求めよ．
  \item $t>1$ のとき，$d(t)<b(t)<\sqrt{a(t)d(t)}$ が成り立つことを示せ．
  \item 極限 $\displaystyle\lim_{t\to1+0}\frac{\sqrt{a(t)d(t)}-b(t)}{(t-1)^3}$ を求めよ．
\end{enumerate}

$c$ を実数の定数とし，$f(x)=c-\sin x$ に対して $\displaystyle g(x)=\int_0^x(x-t)f(t)\,dt$ とおく．
\begin{enumerate}
  \item $g(x)$ を積分を用いずに表し，$g(x+y)+g(x-y)-2g(x)$ を計算せよ．
  \item すべての実数 $x$ と，$|y|\geqq\pi$ をみたすすべての実数 $y$ について $g(x+y)+g(x-y)\geqq2g(x)$ が成り立つような $c$ の最小値を求めよ．
  \item すべての実数 $x$ と，$|y|\geqq\dfrac\pi2$ をみたすすべての実数 $y$ について $g(x+y)+g(x-y)\geqq2g(x)$ が成り立つような $c$ の最小値を求めよ．
\end{enumerate}

座標平面において，点 $\mathrm P(0,1)$ を中心とする半径1の円を $C$ とし，原点を O とする．$a>0$ とし，直線 $y=a(x+1)$ と $C$ との2つの交点を Q，R とする．
\begin{enumerate}
  \item $0<a<1$ のとき，四角形 OQPR の面積 $U(a)$ を求めよ．また，$U(a)$ の最大値とそのときの $a$ を求めよ．
  \item $a>0$ のとき，三角形 OQR の面積 $T(a)$ を求めよ．また，$T(a)$ の最大値とそのときの $a$ を求めよ．
\end{enumerate}

$0<t<1$ に対し，$r(t)=\dfrac{\log(1-t)}{\log(1-t^2)}$ とおく．
\begin{enumerate}
  \item $\dfrac1t+\dfrac12-\dfrac t2<r(t)<\dfrac1t+\dfrac12$ を示せ．
  \item $0.9999^{10050}<0.99^{100}<0.9999^{10049}$ を示せ．
  \item $\displaystyle\lim_{t\to+0}\Bigl\{r(t)-\frac1t\Bigr\}$ を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の2点 P，Q は，ともに $x$ 座標が $0$ 以上であり，線分 PQ の長さは正の定数 $L$ に等しいとする．線分 PQ の中点の $y$ 座標を $h$ とする．
\begin{enumerate}
  \item 直線 PQ の傾きを $m$ とする．このような P，Q が存在するための $m$ の条件を $L$ を用いて表せ．
  \item $h$ の最小値を $L$ で表せ．
\end{enumerate}

\begin{enumerate}
  \item すべての正の実数 $x,y$ に対して $\sqrt[3]x+\sqrt[3]y\leqq k\sqrt[3]{2x+y}$ が成り立つような実数 $k$ の最小値を求めよ．
  \item すべての正の実数 $x,y$ に対して $m\sqrt[3]{2x+y}\leqq\sqrt[3]x+\sqrt[3]y$ が成り立つような実数 $m$ の最大値を求めよ．
\end{enumerate}

$a$ を実数の定数とし，$0<x<\pi$ において
\[
g(x)=\frac{x}{\sin x}+a\cos x,\qquad h(x)=\frac{\sin x-x\cos x}{\sin^3x}
\]
と定める．
\begin{enumerate}
  \item $h(x)$ は $0<x<\pi$ で単調に増加することを示し，$\displaystyle\lim_{x\to+0}h(x)$ を求めよ．
  \item $\displaystyle\lim_{x\to+0}g(x)$，$\displaystyle\lim_{x\to\pi-0}g(x)$ を調べ，$g(x)$ が $0<x<\pi$ において最小値をもつような $a$ の値の範囲を求めよ．
  \item $g(x)$ が $x=\dfrac{2}{3}\pi$ で最小値をとるような $a$ の値と，そのときの最小値を求めよ．
\end{enumerate}

$0<x<\dfrac\pi2$ の範囲の曲線 $y=\cos x$ を考える．$0<t<\dfrac\pi2$ に対し，点 $\mathrm P(t,\cos t)$ におけるこの曲線の接線が $x$ 軸，$y$ 軸と交わる点をそれぞれ Q，R とし，$\triangle\mathrm{OQR}$ の面積を $S(t)$ とする（O は原点）．また，$0<s<\dfrac\pi2$ に対し $T(s)=s\cos s$ とする．
\begin{enumerate}
  \item 任意の $s,\ t\ \left(0<s<\dfrac\pi2,\ 0<t<\dfrac\pi2\right)$ に対して $S(t)\geqq 2T(s)$ が成り立つことを示し，等号が成り立つ $(s,t)$ を求めよ．
  \item $S(t)$ は最小値 $m$ を，$T(s)$ は最大値 $M$ をもち，$m=2M$ であることを示せ．また，$S(t)$ が最小となるとき P は線分 QR の中点であることを示せ．
  \item $\dfrac{\sqrt2}{4}\pi<m<\dfrac{\sqrt2}{64}(4+\pi)^2$ を示せ．
\end{enumerate}

$a$ を正の定数とし，$f(x)=\cos x+ax^2$ とする．$-\dfrac\pi2\leqq x\leqq\dfrac\pi2$ における $f(x)$ の最大値・最小値について次の問いに答えよ．
\begin{enumerate}
  \item $f(x)$ が $x=0$ で最大値をとるような $a$ の範囲を求めよ．
  \item $f(x)$ が $x=0$ で最小値をとるような $a$ の範囲を求めよ．
  \item $a=\dfrac1\pi$ のときの最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 直線 $y=px+q$ が，曲線 $y=\log x$ とも曲線 $y=e^x$ とも共有点をもたないために $p$ と $q$ がみたすべき必要十分条件を求めよ．
  \item 方程式 $(x+1)-(x-1)\log x=0$ は $0<x<1$ の範囲にただ1つの解 $\alpha$ をもつことを示せ．さらに，(1) の条件をみたす $q$ が存在するような $p$ の範囲は $\alpha<p<\dfrac1\alpha$ であることを示せ．
\end{enumerate}

$n$ を正の整数とし，$x_1,x_2,\dots,x_n$ を相異なる $n$ 個の自然数とする（$x_k\leqq n$ とは限らない）．
\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^n\frac{x_k}{k^2+1}\geqq\sum_{k=1}^n\frac{k}{k^2+1}$ を示せ．また，等号が成り立つための条件を求めよ．
  \item $\displaystyle\sum_{k=1}^n\frac{x_k}{k^2+1}>\log(n+1)-\frac12$ を示せ．ただし，$e>2.7$ は用いてよい．
\end{enumerate}

凸四角形 ABCD が $\mathrm{AB}=\mathrm{BC}=1$，$\mathrm{CD}=2$ をみたしながら動く．
\begin{enumerate}
  \item 四角形 ABCD の面積の最大値を求めよ．
  \item 面積が最大となるときの辺 AD の長さを求めよ．
  \item 面積が最大となるとき，4点 A，B，C，D は辺 AD を直径とする1つの円周上にあることを示せ．
\end{enumerate}

\begin{enumerate}
  \item $0<x<\dfrac{\pi}{2}$ のとき $\tan x>x+\dfrac{x^3}{3}$ であることを示せ．
  \item $x>0$ のとき $e^x<1+x+\dfrac{x^2}{2}+\dfrac{x^3}{6}e^x$ であることを示せ．
  \item $e^{\frac{\pi}{180}}-1-\dfrac12\left(\dfrac{\pi}{180}\right)^2$ と $\tan\dfrac{\pi}{180}$ の大小を比較せよ．
\end{enumerate}

$x>0$ で定義された関数 $f(x)=x\log x$ を考える．正の数 $a$，$b$ が $a<b$ かつ $f(a)=f(b)$ をみたすとする．
\begin{enumerate}
  \item $a<\dfrac1e<b<1$ であることを示せ．
  \item $\dfrac2e<a+b<1$ であることを示せ．
  \item $ab<\dfrac1{e^2}$ であることを示せ．
\end{enumerate}

関数 $f(x)$ は $x=0$ を含むある開区間 $I$ で定義され，$I$ で2回微分可能であって，$I$ のすべての $x$ に対し $f(x)>0$，$f'(x)\neq0$ をみたすとする．$k=f(0)$ とおく．曲線 $y=f(x)$ 上の点 $\mathrm P(x,f(x))$ における接線と $x$ 軸の交点を $\mathrm T(t(x),0)$，P における法線と $x$ 軸の交点を $\mathrm Q(q(x),0)$ とする．さらに，次の条件を考える．
\[
(*)\quad I\ \text{のすべての}\ x\ \text{に対し，原点 O は線分 TQ の中点である．}
\]
\begin{enumerate}
  \item $t(x)$，$q(x)$ を $x$，$f(x)$，$f'(x)$ を用いて表せ．また，$(*)$ が成り立つとき，$I$ のすべての $x$ に対して $\mathrm{OP}=\mathrm{OT}=\mathrm{OQ}$ であることを示せ．
  \item $u(x)=\{f(x)\}^2$ とおく．$(*)$ は「$I$ のすべての $x$ に対し $u(x)=xu'(x)+\dfrac{\{u'(x)\}^2}4$」と同値であることを示せ．さらに，$(*)$ が成り立つような $f(x)$ をすべて求め，$k$，$x$ を用いて表せ．
  \item (2) で求めた各 $f(x)$ について，曲線 $y=f(x)$ は原点 O を焦点とするある放物線の一部であることを示し，その放物線の準線の方程式を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 開区間 $I$ で微分可能な関数 $f(x),g(x)$ があり，$I$ で $f(x)\neq0$ とする．$F(x)=\dfrac{g(x)}{f(x)}$ が $I$ 内の点 $x=\alpha$ で最大値または最小値をとり，$f'(\alpha)\neq0$ ならば，$F(\alpha)=\dfrac{g'(\alpha)}{f'(\alpha)}$ であることを示せ．
  \item $F(x)=\dfrac x{e^x+1}$ は実数全体で最大値 $M$ をもつことを示し，$M$ が $Me^{M+1}=1$ をみたすこと，および $F(x)$ は $x=M+1$ で最大となることを示せ．
  \item $\dfrac14<M<\dfrac27$ を示せ．ただし $2.7<e<3$ を用いてよい．
\end{enumerate}

ひし形 ABCD と，半径 $1$ の円 $K_1$，半径 $2$ の円 $K_2$ が次の条件 (ア)，(イ)，(ウ) をすべてみたしている．
\begin{itemize}
  \item[(ア)] $K_1$ は直線 AB と直線 AD の両方に接し，$K_2$ は直線 BA と直線 BC の両方に接する．
  \item[(イ)] $K_1$，$K_2$ の周および内部は，ひし形 ABCD の周および内部に含まれる．
  \item[(ウ)] $K_1$ と $K_2$ は外接する．
\end{itemize}
このようなひし形 ABCD について，次の問いに答えよ．
\begin{enumerate}
  \item 1辺の長さ AB の最小値を求めよ．
  \item 面積の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての実数 $x$ に対して $\sin x=f(x)+g(x)\cos x$ が成り立つような実数係数の多項式 $f(x),g(x)$ は存在しないことを示せ．
  \item $0\leqq x\leqq1$ をみたすすべての $x$ に対して $\sin x=f(x)$ が成り立つような実数係数の多項式 $f(x)$ は存在しないことを示せ．
  \item $0\leqq x\leqq1$ をみたすすべての $x$ に対して $f(\sin x)=x$ が成り立つような実数係数の多項式 $f(t)$ は存在しないことを示せ．
\end{enumerate}

$N>1$ とし，$n$ を正の整数とする．$1=x_0<x_1<\cdots<x_n=N$ をみたす実数 $x_0,x_1,\dots,x_n$ をとり，曲線 $y=\dfrac1x$ 上の点 $\mathrm P_k\left(x_k,\dfrac1{x_k}\right)$（$k=0,1,\dots,n$）を考える．$n\geqq2$ のとき，$(n+1)$ 角形 $\mathrm P_0\mathrm P_1\cdots\mathrm P_n$ の面積を $S$ とし，$n=1$ のときは $S=0$ とする．
\begin{enumerate}
  \item $r_k=\dfrac{x_k}{x_{k-1}}$（$k=1,2,\dots,n$）とおくとき，
  \[
    S=\frac12\left\{N-\frac1N-\sum_{k=1}^{n}\left(r_k-\frac1{r_k}\right)\right\}
  \]
  が成り立つことを示せ．
  \item $N$ と $n$ を固定して $x_1,\dots,x_{n-1}$ を動かすとき，$S$ の最大値 $M_n$ と，最大値を与える $x_k$ を求めよ．
  \item $N$ を固定するとき，$\displaystyle\lim_{n\to\infty}M_n$ を求めよ．さらに，その値が線分 $\mathrm P_0\mathrm P_n$ と曲線 $y=\dfrac1x$ で囲まれた部分の面積に等しいことを示せ．
\end{enumerate}

実数 $a$ に対して，曲線 $C_a:\ y=x^2+a\cos x$ を考える．曲線 $C_a$ 上の相異なる2点で $C_a$ に接する直線を，$C_a$ の\textbf{複接線}とよぶ．
\begin{enumerate}
  \item $C_a$ が複接線をもつような実数 $a$ の値の範囲を求めよ．
  \item $a=\pi$ とする．$C_\pi$ の複接線のうち，「すべての実数 $x$ に対して，$C_\pi$ 上の点 $(x,\ x^2+\pi\cos x)$ が直線の下側にない（直線上にあるか上側にある）」という条件をみたすものをすべて求めよ．
\end{enumerate}

座標平面上に4点 A$(1,\,1)$，B$(-1,\,1)$，C$(-1,\,-1)$，D$(1,\,-1)$ をとる．$x$ 軸上の2点 P$(p,\,0)$，Q$(q,\,0)$（$-1\leqq p\leqq1$，$-1\leqq q\leqq1$）を選び，線分 PA，PD，QB，QC，PQ の5本の道を作る．PA，PD，QB，QC の4本は長さ1あたり費用1，PQ は長さ1あたり費用 $k$（$k$ は正の定数）かかるとし，総費用を
\[
T=\mathrm{PA}+\mathrm{PD}+\mathrm{QB}+\mathrm{QC}+k\cdot\mathrm{PQ}
\]
とする（P$=$Q のときは $\mathrm{PQ}=0$ とする）．
\begin{enumerate}
  \item $p,\ q$ を動かすときの $T$ の最小値 $m(k)$ と，最小値を与える $p,\ q$ をすべて求めよ．
  \item $m(k)=5$ となる $k$ の値を求めよ．
\end{enumerate}

座標平面で，半径 $1$ の円 $C_1$ は $x$ 軸の上側で，半径 $2$ の円 $C_2$ は $x$ 軸の下側で，ともに原点 O において $x$ 軸に接している．時刻 $t=0$ から，2円はそれぞれ $x$ 軸に接したまま $x$ 軸に沿ってすべらずに転がり，どちらの中心も $x$ 軸の正の向きに速さ $1$ で動く．$C_1$ 上の点 P と $C_2$ 上の点 Q は，時刻 $0$ においてともに O にあったとする．
\begin{enumerate}
  \item 時刻 $t$ における P，Q の座標を $t$ で表せ．
  \item $0\leqq t\leqq4\pi$ における線分 PQ の長さの最大値と，それを与える $t$ をすべて求めよ．
\end{enumerate}

実数全体で定義された関数 $f(x),\ g(x),\ h(x)$ は $x=0$ で微分可能で，$f(0)=g(0)=h(0)=0$ をみたす．曲線 $y=f(x)$，$y=g(x)$，$y=h(x)$ の原点における接線は3本とも異なり，そのどの2本のなす角も $60^\circ$ である．さらに実数の定数 $a,\ b,\ c$ があって，$\varphi$ が $f,\ g,\ h$ のいずれであっても
\[
\varphi'(0)=\lim_{x\to0}\frac{ax^2+bx\varphi(x)+c\{\varphi(x)\}^2}{x^2+\{\varphi(x)\}^2}
\]
が成り立つという．
\begin{enumerate}
  \item $b$ の値を求め，$c$ を $a$ で表せ．
  \item 逆に，任意の実数 $a$ に対し，$b,\ c$ を (1) で求めた値とすると，上の条件をすべてみたす関数 $f,\ g,\ h$ が存在することを示せ．
  \item $a=1$ のとき，3本の接線の傾きを求めよ．
\end{enumerate}

底面が1辺の長さ1の正方形で高さが $a$ $(a>0)$ の直方体 $K$ がある．$K$ の8つの頂点と，$K$ の中心（4本の対角線の交点）G の計9点を中心として，半径 $r$ の球を9個つくる．どの2つの球の内部も共有点をもたないような $r$ の最大値を $r(a)$ とし，$r=r(a)$ のとき9個の球の $K$ に含まれる部分の体積の和を $V(a)$ とする．
\begin{enumerate}
  \item $r(a)$ を求めよ．
  \item $F(a)=\dfrac{V(a)}{a}$（$K$ の体積に対する割合）を求め，$a>0$ における $F(a)$ の増減を調べよ．
  \item $F(a)$ の最大値と，そのときの $a$ を求めよ．
\end{enumerate}

以下，$\log x$ は自然対数を表す．$\alpha$ は $0<\alpha<1$ をみたす定数とし，$x>0$ で定義された関数
\[
  f_\alpha(x)=e^{x^\alpha}
\]
を考える．
\begin{enumerate}
  \item 曲線 $y=f_\alpha(x)$ はただ1つの変曲点をもつことを示し，その座標 $(x_\alpha,y_\alpha)$ を求めよ．
  \item $x_\alpha=y_\alpha$ となる $\alpha$（$0<\alpha<1$）がただ1つ存在することを示せ．また，その $\alpha$ は $\dfrac13<\alpha<\dfrac25$ をみたすことを示せ．ただし $\log2>0.69$ であることは用いてよい．
\end{enumerate}

\begin{enumerate}
  \item $x>1$，$0<y\leqq\dfrac56\pi$ のとき，$x\sin y>\sin xy$ が成り立つことを示せ．
  \item $y=\dfrac9{10}\pi$ とする．$x>1$ であって $x\sin y\leqq\sin xy$ となる $x$ の例を1つあげ，それが確かにこの不等式をみたすことを示せ．
\end{enumerate}

$f(x)=xe^{-x}$ とする．整数 $N$ に対し，$m+n=N$ かつ $m\leqq n$ をみたす整数の組 $(m,n)$ を考え，$f(m)+f(n)$ の値が最大となる組 $(m,n)$ を求めたい．必要ならば $2.7<e<2.8$ であることを用いてよい．
\begin{enumerate}
  \item $N=4$ の場合と $N=5$ の場合について，$f(m)+f(n)$ が最大となる組 $(m,n)$ をそれぞれ求めよ．
  \item $N\geqq6$ のとき，$f(m)+f(n)$ が最大となる組 $(m,n)$ を $N$ を用いて表せ．
  \item $N\leqq3$ のとき，$f(m)+f(n)$ が最大となる組 $(m,n)$ を $N$ を用いて表せ．
\end{enumerate}

$f(x)=e^{-|x|}$ とする．曲線 $y=f(x)$ 上の点 A$(a,\ f(a))$ を固定する．$x$ 軸上に2点 B，C をとり，不等式 $y\leqq f(x)$ の表す領域に含まれる三角形 ABC を考える．このような三角形のうち最大の面積をもつものの面積を $S(a)$ とする．
\begin{enumerate}
  \item $S(0)$ を求めよ．
  \item $a>0$ とする．方程式 $w-\log w=2a+1$ は $w>1$ の範囲にただ1つの解をもつことを示せ．また，その解を $w_a$ とするとき，$S(a)=\dfrac{(w_a+1)e^{-a}}{2}$ であることを示せ．
  \item $a$ が実数全体を動くとき，$S(a)$ の最大値と，最大値を与える $a$ の値を求めよ．
\end{enumerate}

$a,\ b$ を実数の定数とし，$b>0$ とする．$g(x)=\dfrac{1+ax^2}{1+bx^2}$ とおく．
\begin{enumerate}
  \item $k=0,\ 1,\ 2,\ 3,\ 4$ のすべてについて，$x=0$ における $k$ 階導関数の値が $\cos x$ と $g(x)$ で一致するような $a,\ b$ を求めよ．ただし，0階導関数は関数そのものとする．
  \item (1) で求めた $a,\ b$ について，すべての実数 $x$ で $\cos x\geqq g(x)$ が成り立つことを示せ．また，等号が成り立つのは $x=0$ のときに限ることを示せ．
  \item $\pi>3.14$ であることを示せ．
\end{enumerate}

曲線 $C:y=\sin x$（$x$ はすべての実数）を考える．
\begin{enumerate}
  \item 直線 $\ell$ は $x$ 軸に平行でなく，$C$ と異なる2点 $(s,\sin s)$，$(t,\sin t)$（$s<t$）で接しているとする．このとき，ある整数 $n$ について $s+t=2n\pi$ となり，$v=\dfrac{t-s}2$ は $\tan v=v$ をみたし，さらに $\ell$ は点 $(n\pi,0)$ を通ることを示せ．
  \item 方程式 $\tan v=v$ の正の解は，各自然数 $k$ について区間 $k\pi<v<k\pi+\dfrac\pi2$ にただ1つずつ存在し，それ以外にはないことを示せ．その解を $v_k$ とするとき，$x$ 軸に平行でなく $C$ と2点以上で接する直線をすべて，$v_k$ を用いて求めよ．
  \item 極限 $\displaystyle\lim_{k\to\infty}k\,|\cos v_k|$ および $\displaystyle\lim_{k\to\infty}k\left(k\pi+\frac\pi2-v_k\right)$ を求めよ．
\end{enumerate}

曲線 $C:\ y=\dfrac1{x^2}\ (x>0)$ と，$a^2b<1$ をみたす正の実数 $a,b$ に対する点 $\mathrm P(a,b)$ を考える．
\begin{enumerate}
  \item P を通る $C$ の接線はちょうど2本あることを示せ．以下，その接点の $x$ 座標を $s,t$（$s<t$）とする．
  \item $\dfrac ts$ は $a^2b$ の値だけで定まり，$a^2b$ が大きいほど $\dfrac ts$ は小さいことを示せ．
  \item 点 P が直線 $x+y=\dfrac32$ の $x>0$，$y>0$ の部分を動くとき，$\dfrac ts$ の最小値と，そのときの P の座標を求めよ．
\end{enumerate}

$N$ を2以上の整数とし，$a_n=n^{N-n}$（$n=1,2,\dots,N$）とする．$a_1,a_2,\dots,a_N$ の最大値を $M$ とする．
\begin{enumerate}
  \item 関数 $f(x)=(N-x)\log x$（$1\leqq x\leqq N$）は，ただ1つの $x=x_N$ で最大となり，$x_N$ は $x_N(1+\log x_N)=N$ をみたすことを示せ．
  \item $N\geqq3$ のとき，$a_n=M$ となる $n$ はただ1つであることを示せ．
  \item $N\geqq3$ のとき (2) の $n$ を $n_N$ とする．$\displaystyle\lim_{N\to\infty}\frac{n_N\log n_N}{N}$ を求めよ．
\end{enumerate}

$t>0$ において定義された関数 $f(t)$ は次の条件 (ア)，(イ) をみたす．
\begin{itemize}
  \item[(ア)] $t>0$ のとき，すべての実数 $x$ に対して不等式 $t\cdot\dfrac{e^x+e^{-x}}2+f(t)\geqq1+x$ が成り立つ．
  \item[(イ)] $t>0$ に対して，等式 $t\cdot\dfrac{e^x+e^{-x}}2+f(t)=1+x$ をみたす実数 $x$ が存在する．
\end{itemize}
\begin{enumerate}
  \item $f(t)$ を求めよ．
  \item $t$ が正の実数全体を動くとき，$xy$ 平面上の曲線 $C_t:\ y=t\cdot\dfrac{e^x+e^{-x}}2+f(t)$ が通過する領域を図示せよ．
\end{enumerate}

\begin{enumerate}
  \item $a,b$ を正の定数とし，$g(t)=\dfrac1bt^a-\log t$ とおく．$t>0$ における $g(t)$ の増減を調べ，最小値を求めよ．
  \item $m$ を正の定数とし，$xy$ 平面において次の条件をみたす点 $(x,y)$ 全体を $D$ とする．
  \begin{center}
  $x>0$，$y>0$ であり，$0<t\leqq1$ をみたすすべての $t$ に対して $\dfrac1yt^x-\log t\geqq m$．
  \end{center}
  $D$ を図示せよ．
  \item $R>\dfrac1m$ とし，$D$ のうち $x\leqq R$ の部分の面積を $S(R)$ とする．$S(R)$ と $\displaystyle\lim_{R\to\infty}S(R)$ を求めよ．
\end{enumerate}

$a,\ b$ を実数とする．実数全体で定義された実数値関数 $f(x)$，$g(x)$ が次の条件をすべてみたすとする．
\begin{itemize}
  \item[(A)] すべての実数 $x,\ y$ について $f(x+y)=f(x)f(y)+g(x)g(y)$
  \item[(B)] すべての実数 $x,\ y$ について $g(x+y)=f(x)g(y)+g(x)f(y)$
  \item[(C)] $f(0)\neq0$
  \item[(D)] $f(x)$，$g(x)$ は $x=0$ で微分可能で，$f'(0)=a$，$g'(0)=b$
\end{itemize}
\begin{enumerate}
  \item 組 $\bigl(f(0),\ g(0)\bigr)$ は $(1,0)$，$\left(\dfrac12,\dfrac12\right)$，$\left(\dfrac12,-\dfrac12\right)$ のいずれかであることを示せ．
  \item 実数全体で定義された関数 $h(x)$ が，すべての実数 $x,\ y$ について $h(x+y)=h(x)h(y)$ をみたし，$x=0$ で微分可能で $h'(0)=k$ であるとする．このとき，$h(x)$ は恒等的に $0$ であるか，$h(x)=e^{kx}$ であるかのいずれかであることを示せ．
  \item 条件 (A)〜(D) をみたす関数の組 $\bigl(f(x),\ g(x)\bigr)$ を，$a,\ b$ の値に応じてすべて求めよ．
\end{enumerate}

曲線 $C:y=f(x)=\dfrac1{1+x^2}$ を考える．
\begin{enumerate}
  \item $C$ 上の点 $(s,f(s))$ における接線と $y$ 軸との交点を $(0,t)$ とする．実数 $t$ を与えたとき，このような点 $(s,f(s))$ の個数を $t$ の値によって答えよ．
  \item 点 Q$\left(-1,\dfrac12\right)$ と $C$ 上の点 P$(s,f(s))$（$s>-1$）を結ぶ線分 QP の両端を除いた部分が，すべて $C$ の下側（$y<f(x)$ の部分）にあるような $s$ の値の範囲を求めよ．
\end{enumerate}

実数 $p>0$ に対して $f(x)=e^{(p+1)x}-e^x$ とおく．
\begin{enumerate}
  \item $f(x)$ が最小となる $x$ の値 $s_p$ を求めよ．
  \item $G(t)=\displaystyle\int_t^{t+1}f(x)\,dx$ とおく．$G(t)$ が最小となる $t$ の値 $t_p$ を求めよ．
  \item 極限 $\displaystyle\lim_{p\to+0}(t_p-s_p)$ と $\displaystyle\lim_{p\to\infty}(t_p-s_p)$ を求めよ．
\end{enumerate}

$xyz$ 空間において，連立不等式 $|x|\leqq1$，$|y|\leqq1$，$|z|\leqq1$ の表す立方体を $Q$ とする．正の実数 $r,h$ に対し，連立不等式 $x^2+y^2\leqq r^2$，$|z|\leqq h$ の表す円柱を $T$ とし，$Q$ と $T$ のいずれか一方のみに含まれる点全体の体積を $W(r,h)$ とする．
\begin{enumerate}
  \item $W(1,h)$ を $h$ の式で表せ．
  \item $1\leqq r\leqq\sqrt2$ のとき，$r=\dfrac1{\cos\theta}$ $\left(0\leqq\theta\leqq\frac\pi4\right)$ とおく．$W(r,1)$ を $\theta$ で表せ．
  \item $r,h$ が正の実数全体を動くとき，$W(r,h)$ の最小値と，それを与える $r,h$ を求めよ．
\end{enumerate}

$a>0$，$b\geqq0$ を定数とし，曲線 $C:y=a\sin x+bx$ を考える．
\begin{enumerate}
  \item $C$ 上の2点における接線で，互いに直交するものが存在するための $a,b$ の条件を求めよ．
  \item $a^2-b^2=1$ とする．$C$ の互いに直交する2本の接線の交点全体の集合を求めよ．
\end{enumerate}

1辺の長さが1の正方形 $K$ がある．3辺の長さの比が $3:4:5$ である三角形 $T$ が $K$ を含む（$K$ のすべての点が $T$ の周または内部にある）とする．
\begin{enumerate}
  \item $T$ の最も長い辺が $K$ のある辺と平行であるとき，$T$ の面積の最小値を求めよ．
  \item $T$ の面積の最小値を求めよ．
\end{enumerate}

座標平面上の曲線 $C:\ y=\dfrac{x}{x^2+1}$ と，$0$ でない実数 $a$ と実数 $b$ で定まる直線 $l:\ y=ax+b$ を考える．$a$ を固定したとき，$C$ と $l$ がちょうど2個の共有点をもつような実数 $b$ の個数を $N(a)$ とする．
\begin{enumerate}
  \item $0$ でないすべての実数 $a$ に対して $N(a)$ を求めよ．
  \item $a=-\dfrac19$ のとき，$C$ と $l$ がちょうど2個の共有点をもつような $b$ の値をすべて求めよ．
\end{enumerate}

$\mathrm{OA}=\mathrm{OB}=1$，$\angle\mathrm{AOB}=\theta$（$0<\theta<\dfrac\pi2$）である二等辺三角形 OAB がある．O を中心とし辺 AB に接する円を $K_{\mathrm O}$，A を中心とし辺 OB に接する円を $K_{\mathrm A}$ とする．三角形 OAB の周および内部と，$K_{\mathrm O}$ の周および内部との共通部分の面積を $S_{\mathrm O}$，三角形 OAB の周および内部と，$K_{\mathrm A}$ の周および内部との共通部分の面積を $S_{\mathrm A}$ とする．
\begin{enumerate}
  \item $S_{\mathrm O}$，$S_{\mathrm A}$ を $\theta$ で表せ．
  \item $S_{\mathrm A}\geqq S_{\mathrm O}$ となる $\theta$ の値の範囲を求めよ．
\end{enumerate}

$n$ を $3$ 以上の整数とし，$B_n(x)=\cos^{2n}x-\sin^{2n}x$ とする．
\begin{enumerate}
  \item $0<x<\dfrac\pi4$ を満たすすべての $x$ に対して $(\cos2x)^p\leqq B_n(x)$ が成り立つような実数 $p$ の範囲を求めよ．
  \item $0<x<\dfrac\pi4$ を満たすすべての $x$ に対して $B_n(x)\leqq(\cos2x)^q$ が成り立つような実数 $q$ の範囲を求めよ．
\end{enumerate}

$f(x)$ は $0\leqq x\leqq1$ で定義された微分可能な関数とする（$x=0,\ 1$ では片側からの微分係数を考える）．
\begin{enumerate}
  \item $\displaystyle\int_0^1f(x)\,dx=\frac{f(1)}2$ が成り立つならば，$0<c<1$ をみたす実数 $c$ で，曲線 $y=f(x)$ 上の点 $(c,\ f(c))$ における接線が原点を通るものが存在することを示せ．
  \item $\displaystyle\int_0^1f(x)\,dx=\frac{f(1)}2$ かつ $\displaystyle\int_0^1xf(x)\,dx=\frac{f(1)}3$ が成り立つならば，(1) のような $c$ が少なくとも $2$ つ存在することを示せ．
  \item $f(x)=x^4+px^3+qx^2$（$p,\ q$ は実数の定数）が (2) の $2$ つの条件をみたすような $p,\ q$ を求めよ．また，そのとき $0<c<1$ で点 $(c,\ f(c))$ における接線が原点を通る $c$ をすべて求めよ．
\end{enumerate}

放物線 $C:\ y=\dfrac{x^2-1}2$ と，単位円板 $D:\ x^2+y^2\leqq1$ を考える．$\dfrac1{\sqrt3}<t<\sqrt3$ をみたす実数 $t$ に対し，$C$ 上の点 $\left(t,\ \dfrac{t^2-1}2\right)$ における $C$ の接線を $l_1$，点 $\left(-\dfrac1t,\ \dfrac{1-t^2}{2t^2}\right)$ における $C$ の接線を $l_2$ とする．
\begin{enumerate}
  \item $l_1$ と $l_2$ は直交し，その交点は直線 $y=-1$ 上にあることを示せ．また，原点と $l_1,\ l_2$ の距離 $d_1,\ d_2$ を $t$ で表し，$l_1,\ l_2$ はいずれも円 $x^2+y^2=1$ と異なる2点で交わることを示せ．
  \item $D$ の点のうち，$l_1$ に関して原点と反対側にある（$l_1$ 上の点は含めない）もの全体を $D_1$，$l_2$ について同様に定めたものを $D_2$ とする．$D_1$ と $D_2$ は共通の点をもたないことを示せ．さらに，$D_1$ と $D_2$ の面積の和を $S(t)$ とするとき，$S(t)$ の最大値と，そのときの $t$ の値を求めよ．
  \item $S(t)$ が最小となる $t$ の値をすべて求めよ．
\end{enumerate}

関数 $f(x)$ は実数全体で2回微分可能で，すべての実数 $x$ に対して $f''(x)>f(x)$ を満たすとする．
\begin{enumerate}
  \item $f(0)\geqq0$ かつ $f(0)+f'(0)\geqq0$ ならば，すべての正の実数 $x$ に対して $f(x)>0$ であることを示せ．
  \item $a>0$，$a+b<0$ を満たす実数 $a,\ b$ を任意にとる．すべての実数 $x$ で $f''(x)>f(x)$ を満たし，$f(0)=a$，$f'(0)=b$ であり，さらに $f(c)=0$ となる正の実数 $c$ が存在するような関数 $f(x)$ を1つ挙げ，それが条件を満たすことを示せ．
  \item $f(0)=1$，$f'(0)=0$ ならば，$0$ でないすべての実数 $x$ に対して $f(x)>\dfrac{e^x+e^{-x}}2$ であることを示せ．
\end{enumerate}

関数 $f(x),\ g(x)$ はすべての実数 $x$ で微分可能で，次の条件(a)，(b)，(c)をみたす．
\begin{itemize}
  \item[(a)] すべての $x$ で $f'(x)=-g(x)$．
  \item[(b)] $f(0)=1$，$g(0)=0$．
  \item[(c)] $f(x)>0$ をみたすすべての $x$ で $g'(x)\geqq f(x)$．
\end{itemize}
\begin{enumerate}
  \item $f(x)=0$ をみたす $x$ が $0<x\leqq\dfrac\pi2$ の範囲に存在することを示せ．
  \item さらに次の条件(d)も成り立つとする．
  \begin{itemize}
    \item[(d)] $f(x)>0$ をみたすすべての $x$ で $g'(x)\leqq 2f(x)$．
  \end{itemize}
  正の数 $b$ が「$f(b)=0$ であり，$0\leqq x<b$ のすべての $x$ で $f(x)>0$」をみたすとき，
  \[
  \frac{\pi}{2\sqrt2}\leqq b\leqq\frac\pi2
  \]
  が成り立つことを示せ．
  \item (a)〜(d)をみたす $f(x),\ g(x)$ で，(2)の $b$ が $\dfrac\pi2$ となるもの，$\dfrac{\pi}{2\sqrt2}$ となるものの例をそれぞれ1組あげよ．
\end{enumerate}

$\mathrm{AB}=1$，$\mathrm{AC}=3$，$\angle\mathrm{BAC}=60^\circ$ である三角形 ABC の辺 AC 上に，A，C と異なる点 D をとる．線分 BD を折り目としてこの三角形を折り曲げ，A が移った点を A$'$ とする．ただし A$'$ は平面 BCD 上にないようにする．
\begin{enumerate}
  \item D を固定したとき，四面体 A$'$BCD の体積の最大値を $\mathrm{AD}=s$ の式で表せ．
  \item D が辺 AC 上を動き，折り方も変えるとき，四面体 A$'$BCD の体積の最大値と，そのときの AD の長さを求めよ．
  \item (2)で体積が最大になるとき，線分 A$'$C の長さを求めよ．
\end{enumerate}

座標平面上の双曲線 $y^2-x^2=1$ の $y>0$ の部分を $H$ とする．$t>0$ に対し，点 $\mathrm Q(t,\ 2\sqrt2\,t)$ を考える．$H$ 上の点 P に対して，P における $H$ の法線（P を通り P における接線に垂直な直線）が Q を通るとき，P を「Q の足」とよぶ．
\begin{enumerate}
  \item 点 $\mathrm P\left(s,\ \sqrt{s^2+1}\right)$ が Q の足であるための条件を，$s$ と $t$ の関係式で表せ．また，そのような $s$ がとりうる値の範囲を求めよ．
  \item Q の足の個数を，$t$ の値によって分類して答えよ．
\end{enumerate}

$d\geqq0$ に対し，中心間の距離が $d$ である半径1の2つの円板（円周とその内部）の共通部分の面積を $L(d)$ とする．
\begin{enumerate}
  \item $0\leqq d\leqq2$ のとき，$d=2\cos\theta$（$0\leqq\theta\leqq\frac\pi2$）とおいて $L(d)$ を $\theta$ で表せ．また，$L(d)$ は $0\leqq d\leqq2$ で減少し（$d_1<d_2$ なら $L(d_1)>L(d_2)$），$L(0)=\pi$，$L(2)=0$ であることを示せ．
  \item 正の数 $a,\ b,\ c$ が与えられている．平面上に3点 $\mathrm P_1,\ \mathrm P_2,\ \mathrm P_3$ を，$\mathrm P_2$ が線分 $\mathrm P_1\mathrm P_3$ 上（両端を除く）にあるようにとり，$\mathrm P_i$ を中心とする半径1の円板を $D_i$ とする．$D_1\cap D_2,\ D_2\cap D_3,\ D_3\cap D_1$ の面積がすべて正で
  \[
  \frac{D_1\cap D_2\text{ の面積}}{a}=\frac{D_2\cap D_3\text{ の面積}}{b}=\frac{D_3\cap D_1\text{ の面積}}{c}
  \]
  となるようにできるための必要十分条件は，$c<a$ かつ $c<b$ であることを示せ．
\end{enumerate}

座標平面上で，原点 O を中心とする半径1の円を $C$ とし，4点 $\left(\frac12,1\right)$，$\left(\frac32,1\right)$，$\left(\frac32,2\right)$，$\left(\frac12,2\right)$ を頂点とする正方形の周および内部を $K$ とする．点 P が $K$ 上を動くとき，P から $C$ に引いた2本の接線の接点を A，B とし，三角形 OAB を直線 AB のまわりに1回転してできる立体の体積を $V$ とする．
\begin{enumerate}
  \item $\mathrm{OP}=d$ とするとき，$V$ を $d$ で表せ．
  \item $V$ の最大値と，最大値を与える点 P の全体を求めよ．
  \item $V$ の最小値と，最小値を与える点 P を求めよ．
\end{enumerate}

$-\dfrac\pi2<x<\dfrac\pi2$ で定義された関数 $f(x)=\tan x+\dfrac1{\cos x}$ を考える．$f(x)$ の第 $n$ 次導関数を $f^{(n)}(x)$ と書き，$f^{(0)}(x)=f(x)$ とする．
\begin{enumerate}
  \item $f'(x)=\dfrac{1+\{f(x)\}^2}2$ が成り立つことを示せ．
  \item すべての自然数 $n$ に対して，$-\dfrac\pi2<x<\dfrac\pi2$ で $f^{(n)}(x)>0$ が成り立つことを示せ．また，$f^{(n)}(0)$（$n=1,2,\dots,6$）を求めよ．
  \item すべての自然数 $n$ に対して $f^{(n)}(0)<(1+\sqrt2)\,n!\left(\dfrac4\pi\right)^n$ が成り立つことを示せ．
\end{enumerate}

$x>0$ で定義された連続関数 $y=f(x)$ が，すべての $x>0$ に対して
\begin{center}
(i) $f(x)>0$　　　(ii) $f(x)-\log f(x)=2(x-\log x)+c$
\end{center}
をみたしている．ここで対数は自然対数，$c$ は定数である．
\begin{enumerate}
  \item このような関数 $f(x)$ が存在するための $c$ の値の範囲を求めよ．
  \item $c=-1$ のとき，(i)，(ii) をみたす連続関数 $f(x)$ はいくつあるか．
  \item $c=-1$ のとき，(2) の関数のうち $x=1$ で微分可能なものをすべて答え，それぞれについて $f'(1)$ を求めよ．
\end{enumerate}

実数全体で微分可能な関数 $f(x)$，$g(x)$ に対し，曲線 $y=f(x)$ の $x=a$ における接線と曲線 $y=g(x)$ の $x=a$ における接線がただ1点で交わるとき，その交点の $y$ 座標を $f*g(a)$ と表す．
\begin{enumerate}
  \item $k$ を実数の定数とし，すべての実数 $x$ で $g(x)>k$ とする．すべての実数 $a$ について2本の接線がただ1点で交わり，かつ $f*g(a)=k$ が成り立つならば，ある定数 $C$ を用いて $f(x)=k+C\{g(x)-k\}$ と表されることを示せ．
  \item $g(x)=e^x$，$f(x)=x^2+px+q$（$p,q$ は実数の定数）とし，$h(x)=\dfrac{f(x)}{g(x)}$ とおく．次の2条件
  \begin{itemize}
    \item[$1^\circ$] $f*g(a)$ が定義されて $f*g(a)=0$
    \item[$2^\circ$] $h(x)$ は $x=a$ で極値をとらない
  \end{itemize}
  をともにみたす実数 $a$ がただ1つ存在するための $p,q$ の条件を求めよ．ただし，$1^\circ$ をみたす実数 $a$ がただ1つであり，その $a$ が $2^\circ$ もみたすことを要求する．
\end{enumerate}

曲線 $C:\ y=e^x$ を考える．
\begin{enumerate}
  \item 座標平面上のどのような円も，$C$ との共有点は4個以下であることを示せ．
  \item 点 $\mathrm P(a,b)$ を中心とする円で $C$ と異なる4点で交わるものが存在するための，実数 $a,b$ がみたす条件を求めよ．
  \item $b=3$ のとき，(2) の条件をみたす $a$ の範囲を求めよ．
\end{enumerate}

$a$ を正の定数，$f(x)$ を実数全体で何回でも微分可能な関数とし，$f^{(0)}(x)=f(x)$，$f^{(m)}(x)$ を $f(x)$ の第 $m$ 次導関数とする．次の条件 (A) をみたす関数 $g(x)$（$x>0$ で定義される）を考える．
\begin{center}
(A)\quad $g(x)$ は $x>0$ で連続であり，各自然数 $n$ に対し，$(n-1)a<x<na$ において $g(x)=f^{(n-1)}\bigl(x-(n-1)a\bigr)$．
\end{center}
\begin{enumerate}
  \item (A) をみたす $g(x)$ が存在するための必要十分条件は，すべての0以上の整数 $m$ について $f^{(m)}(a)=f^{(m+1)}(0)$ が成り立つことであることを示せ．
  \item $f(x)=e^{px}+e^{qx}$（$p,q$ は $p<q$ をみたす自然数）とする．(A) をみたす $g(x)$ が存在するような $p,q,a$ をすべて求め，そのときの $g(x)$ を求めよ．
  \item $f(x)=e^{px}+e^{qx}$（$p,q$ は $p<q$ をみたす実数）とする．(A) をみたす $g(x)$ が存在するような組 $(p,q)$ があるための $a$ の条件は $0<a<\dfrac1e$ であり，このとき条件をみたす組 $(p,q)$ はただ1つであることを示せ．
\end{enumerate}

$x>0$ で定義された関数
\[
f(x)=ax\,e^{x}\log x+\frac{b\,e^{x-1}}{x}
\]
（$a,b$ は定数）について，曲線 $y=f(x)$ の点 $(1,\,f(1))$ における接線の方程式は $y=2e(x-1)+3$ である．ただし $\log$ は自然対数を表す．
\begin{enumerate}
  \item $a,\ b$ の値を求めよ．
  \item すべての $x>0$ に対して $f(x)>2$ が成り立つことを示せ．
  \item $f(x)$ は $x>0$ において最小値をもつことを示し，その最小値 $m$ が $2<m<3$ をみたすことを示せ．
\end{enumerate}

$f(x)=e^{x}-e^{-x}-2x$ とし，実数の定数 $c$ に対して $g_c(x)=f(3x)-c\,f(x)$ とおく．ただし $\log$ は自然対数を表す．
\begin{enumerate}
  \item すべての $x>0$ に対して $g_c(x)>0$ が成り立つような $c$ の最大値を求めよ．
  \item 次の不等式を証明せよ．
  \[
  \frac{47\sqrt2}{96}<\log2<\frac{2+3\sqrt2}{9}
  \]
  \item $1.4142<\sqrt2<1.4143$ を用いて，$0.692<\log2<0.694$ を示せ．
\end{enumerate}

実数 $a,\ b$ に対し，$f(x)=a\left(e^{x-1}+e^{1-x}\right)+x^2-2x+b$ とする．
\begin{enumerate}
  \item $t\neq0$ のとき $e^t+e^{-t}-2>t^2$ であることを示せ．
  \item 方程式 $f(x)=0$ がただ1つの実数解をもつような点 $(a,b)$ 全体を求めよ．
  \item $b=1-2a$ のとき，方程式 $f(x)=0$ の異なる実数解の個数を，$a$ の値で分類して答えよ．
\end{enumerate}

$a,b$ を正の実数とし，$f(x)=a^x+b^x-x-2$ とする．
\begin{enumerate}
  \item 方程式 $f(x)=0$ の実数解がちょうど1個であるような $(a,b)$ の条件を求めよ．
  \item 方程式 $f(x)=0$ の実数解がちょうど2個であるとき，それは $0$ と $0$ でない数 $\gamma$ であることを示し，$\gamma>0$ となるための $a,b$ の条件を求めよ．
\end{enumerate}

$0$ でない実数の定数 $T$ が存在して，すべての実数 $x$ に対して $f(x+T)=Tf(x)$ が成り立つような，実数全体で定義された関数 $f(x)$ 全体の集合を $M$ とする．$e$ は自然対数の底，対数は自然対数とする．
\begin{enumerate}
  \item $a$ を正の定数とする．$f(x)=a^x$ が $M$ に属するような $a$ の値の範囲を求めよ．
  \item $f(x)$ は $M$ に属し，ある正の定数 $B$ に対してすべての実数 $x$ で $|f(x)|\leqq B$ をみたし，さらに $f(x_0)\neq0$ となる実数 $x_0$ があるとする．このとき，$f(x+T)=Tf(x)$ がすべての $x$ で成り立つような $0$ でない定数 $T$ は $1$ または $-1$ に限ることを示せ．
  \item 正の定数 $k$ に対して $f(x)=\sin\pi x+\sin kx$ とする．$f(x)$ が $M$ に属するような $k$ をすべて求めよ．
\end{enumerate}

$k$ を実数とし，$x\neq0$ で定義された関数
\[
q(x)=\begin{cases}\dfrac{x^2}2+k\log x & (x>0)\\[2mm] \dfrac{x^2}2+\log(-x)+2kx & (x<0)\end{cases}
\]
を考える．次の条件 (P) を考える．
\begin{center}
(P)：0でない任意の実数 $x_1$ に対して，$q'(x_2)=q'(x_1)$ をみたす0でない実数 $x_2$（$x_2\neq x_1$）がただ1つ存在する．
\end{center}
\begin{enumerate}
  \item $k=1$ のとき (P) は成り立たないことを示せ．
  \item (P) が成り立つような $k$ の値をすべて求めよ．
\end{enumerate}

solutions.tex:
$x>0$ で $h(x)=q'(x)=x+\dfrac kx$，$x<0$ で $g(x)=q'(x)=x+\dfrac1x+2k$ である（$x<0$ で $\{\log(-x)\}'=\dfrac{-1}{-x}=\dfrac1x$）．条件 (P) は「$q'(x_1)$ の値をとる0でない実数が，$x_1$ 以外にちょうど1つある」ということである．

{\bf $g$ の様子．}$g'(x)=1-\dfrac1{x^2}=\dfrac{(x+1)(x-1)}{x^2}$ は $x<-1$ で正，$-1<x<0$ で負．$B=g(-1)=2k-2$ とおく．$\displaystyle\lim_{x\to-\infty}g(x)=-\infty$，$\displaystyle\lim_{x\to-0}g(x)=-\infty$ だから，中間値の定理と単調性より，$x<0$ において
\begin{center}
値 $B$ は $x=-1$ でただ1回，$v<B$ である値 $v$ はちょうど2回（$x<-1$ と $-1<x<0$ に1回ずつ）とられ，$v>B$ である値はとられない．
\end{center}

{\bf $h$ の様子．}$h'(x)=1-\dfrac k{x^2}$．
\begin{itemize}
  \item $k>0$ のとき：$h$ は $0<x\leqq\sqrt k$ で減少，$x\geqq\sqrt k$ で増加し，$A=h(\sqrt k)=2\sqrt k$．$\displaystyle\lim_{x\to+0}h(x)=\infty$，$\displaystyle\lim_{x\to\infty}h(x)=\infty$ だから，$x>0$ において値 $A$ は1回，$v>A$ は2回とられ，$v<A$ はとられない．
  \item $k\leqq0$ のとき：$h'(x)>0$ で $h$ は増加．したがって $x>0$ において各値は高々1回しかとられない．
\end{itemize}

(1) $k=1$ のとき $A=2$，$B=0$．$x_1=1$ とすると $q'(1)=2$．$x>0$ で値2をとるのは $x=1$ だけで，$x<0$ では $g(x)\leqq0<2$．よって $x_2$ が存在せず，(P) は成り立たない．\hfill$\square$

(2) {\bf $k<0$ のとき．}$\displaystyle\lim_{x\to+0}h(x)=-\infty$，$\displaystyle\lim_{x\to\infty}h(x)=\infty$ で $h$ は増加だから，$x>0$ で各実数値をちょうど1回とる．$x_1=-2$ とすると $v=g(-2)=2k-\dfrac52<B$ だから，$v$ は $x<0$ で $-2$ 以外にもう1回，$x>0$ で1回とられ，$x_2$ の候補が2つあるので (P) は成り立たない．

{\bf $k=0$ のとき．}$h(x)=x$．$x_1=1$ とすると値1を $x>0$ でとるのは $x=1$ だけで，$x<0$ では $g(x)\leqq B=-2<1$．$x_2$ が存在せず不適．

{\bf $k>0$ のとき．}
\begin{itemize}
  \item $A>B$ なら，$x_1=\sqrt k$ とすると値 $A$ は $x>0$ で $\sqrt k$ だけでとられ，$x<0$ では $g\leqq B<A$．$x_2$ が存在せず不適．
  \item $A<B$ なら，$x_1=-1$ とすると値 $B$ は $x<0$ で $-1$ だけでとられ，$x>0$ では $B>A$ なので2回とられる．$x_2$ の候補が2つあり不適．
  \item $A=B$ なら，任意の $x_1\neq0$ について $v=q'(x_1)$ とする．$x_1>0$ なら $v\geqq A$，$x_1<0$ なら $v\leqq B=A$ である．$v=A$ のとき $v$ をとる0でない $x$ は $\sqrt k$ と $-1$ のちょうど2つ．$v>A$ のとき $x>0$ でちょうど2回，$x<0$ では0回．$v<A$ のとき $x<0$ でちょうど2回，$x>0$ では0回．いずれも $x_1$ 以外にちょうど1つの $x_2$ があり，(P) が成り立つ．
\end{itemize}
$A=B$ は $2\sqrt k=2k-2$，すなわち $(\sqrt k)^2-\sqrt k-1=0$．$\sqrt k>0$ より $\sqrt k=\dfrac{1+\sqrt5}2$，$k=\dfrac{6+2\sqrt5}4=\dfrac{3+\sqrt5}2$．

以上より $\boldsymbol{k=\dfrac{3+\sqrt5}2}$．

statement.tex:
$k$，$d$ を正の定数とし，$f(x)=x^2(x-d)^2e^{kx}$ とする．
\begin{enumerate}
  \item $f(x)$ が極値をとる $x$ の値（極値点）はちょうど4つあることを示し，そのそれぞれで $f(x)$ が極大値・極小値のどちらをとるかを答えよ．
  \item 4つの極値点から3つを選び，適当な順に並べると等差数列になるようにできるための $kd$ の値をすべて求めよ．
  \item どのような正の定数 $k$，$d$ と実数 $t$ に対しても，4つの極値点と $t$ の合わせて5つの数を，どのような順に並べても等差数列にはならないことを示せ．
\end{enumerate}

$a$ を正の実数とし，$f(x)=\log x-ax\ (x>0)$ とする．
\begin{enumerate}
  \item $f(x)$ の増減を調べよ．
  \item 次の条件をみたす実数 $\alpha$，$\beta$ が存在するような $a$ の値の範囲を求めよ．
  \[1\leqq\alpha<\beta\leqq4,\qquad\beta\geqq2\alpha,\qquad f(\alpha)=f(\beta).\]
\end{enumerate}

$a$ を実数とし，$f(x)=(x-a)\log x\ (x>0)$ とする．
\begin{enumerate}
  \item $a>0$ のとき，$f(x)$ は最小値をもつことを示せ．また，最小値をとる $x$ を $x_0$ とするとき，最小値を $x_0$ だけの式で表せ．
  \item すべての $x>0$ に対して $f(x)\geqq-e$ が成り立つような $a$ の値の範囲を求めよ．
\end{enumerate}

$f(x)=\log x+\dfrac1x\ (x>0)$ とし，$a$ は $a>1$ をみたす定数とする．
\begin{enumerate}
  \item 方程式 $f(x)=a$ はちょうど2つの実数解をもつことを示せ．以下，その2つの解を $x_1,\ x_2\ (x_1<x_2)$ とする．
  \item $x_1x_2>1$ を示せ．
  \item $\dfrac1{x_1}+\dfrac1{x_2}>2$ を示せ．
\end{enumerate}

関数 $f(x)=xe^{x}$ について，曲線 $C:\ y=f(x)$ 上の点 $\mathrm P(t,\ te^{t})$ における $C$ の接線を $\ell_t$ とする．
\begin{enumerate}
  \item $f(x)$ の増減と $C$ の凹凸を調べよ．
  \item $\ell_t$ と $C$ の共有点が P だけであるような実数 $t$ の値の範囲を求めよ．
\end{enumerate}

$f(x)=x\log x\ (x>0)$ とし，$a$ を $-\dfrac1e<a<0$ をみたす定数とする．
\begin{enumerate}
  \item 方程式 $f(x)=a$ はちょうど2つの実数解 $x_1,x_2$（$x_1<x_2$）をもち，$0<x_1<\dfrac1e<x_2<1$ であることを示せ．
  \item $x_2-x_1<1+2a+\dfrac1{e^2}$ を示せ．
  \item $x_2-x_1>1+ea$ を示せ．
\end{enumerate}

$a>0$ とし，$f(x)=e^{ax}\sin x\ (x\geqq0)$ とする．$f(x)$ が極値をとる $x$ を小さい順に $x_1,x_2,x_3,\cdots$ とする．
\begin{enumerate}
  \item 数列 $\{f(x_n)\}$ は等比数列であることを示し，その公比を求めよ．
  \item $a\geqq1$ ならば，すべての正の整数 $n$ について $x_n^{\,2}<|f(x_n)|$ が成り立つことを示せ．
  \item $a=\dfrac12$ のとき，$x_1^{\,2}>|f(x_1)|$ であることを示せ．ただし $e<2.72$，$\pi>3.14$，$\sqrt5>2.236$ を用いてよい．
\end{enumerate}

$\log$ は自然対数とする．
\begin{enumerate}
  \item 実数の組 $(a,\,b)$ で，次の条件をみたすものをすべて求めよ．
  \begin{center}
  「ある正の数 $t$ が存在して，$0<x<t$ をみたすすべての $x$ について\\
  $1+bx>0$ かつ $\left|\log(1+x)-\dfrac{ax}{1+bx}\right|<x^3$ が成り立つ．」
  \end{center}
  \item $\dfrac{17}{25}<\log2<\dfrac7{10}$ を示せ．
\end{enumerate}

$a$ を正の定数とし，$x>0$ で定義された関数 $g(x)=x-\log(1+x)$ を考える．
\begin{enumerate}
  \item $x>0$ のとき，$\dfrac{x^2}{2(1+x)}<g(x)<\dfrac{x^2}{2}$ が成り立つことを示せ．
  \item 方程式 $g(x)=a$ は $x>0$ の範囲にただ1つの解をもつことを示せ．
  \item (2) の解を $x_0$ とする．$\sqrt{2a}<x_0<a+\sqrt{a^2+2a}$ を示し，$\displaystyle\lim_{a\to+0}\frac{x_0}{\sqrt a}$ を求めよ．
\end{enumerate}

$a,b$ を実数とする．2曲線 $y=e^x-ax\ (x\geqq0)$ と $y=b\sqrt x\ (x\geqq0)$ が共有点をもつとする．
\begin{enumerate}
  \item $a=0$ のとき，$b$ のとりうる値の範囲を求めよ．
  \item $a^2+b^2$ の最小値を求めよ．また，最小値をとるときの $a,b$ を求めよ．
\end{enumerate}

$a$，$b$ を実数とし，$f(x)=\cos ax+\log(1+bx^2)$ を $1+bx^2>0$ をみたす $x$ の範囲で考える．ここで「$f(x)$ が $x=0$ で極大となる」とは，正の数 $\delta$ があって，$0<|x|<\delta$ をみたす（定義域内の）すべての $x$ で $f(x)<f(0)$ となることをいう．
\begin{enumerate}
  \item すべての実数 $u$ について $1-\dfrac{u^2}2\leqq\cos u\leqq1-\dfrac{u^2}2+\dfrac{u^4}{24}$ が成り立つことを示せ．また，$y>-1$ のとき $\log(1+y)\leqq y$，$y\geqq0$ のとき $y-\dfrac{y^2}2\leqq\log(1+y)\leqq y-\dfrac{y^2}2+\dfrac{y^3}3$ が成り立つことを示せ．
  \item $f(x)$ が $x=0$ で極大となるような点 $(a,b)$ の範囲を求めよ．
\end{enumerate}

$f(x)$ を実数全体で微分可能な関数とする．点 $\mathrm M(p,q)$ に対して $s(x)=(x-p)^2+\{f(x)-q\}^2$ とおき，$s(x)$ が $x=x_0$ で（実数全体での）最小値をとるとき，点 $(x_0,f(x_0))$ を「M の最近点」とよぶ．$f(x)$ は次の条件 (＊) をみたすとする．
\begin{center}
(＊)：どの実数 $t$ に対しても，曲線 $y=f(x)$ 上のある点 P が\\
2点 $\mathrm M_1(t-f(t),\ f(t)+1)$，$\mathrm M_2(t+f(t),\ f(t)-1)$ の両方の最近点になっている．
\end{center}
\begin{enumerate}
  \item 各実数 $t$ について，(＊) の点 P は $(t,f(t))$ に限ることを示せ．さらに，すべての $t$ で $f'(t)=f(t)$ であることを示せ．
  \item さらに $f(0)=1$ とする．$f(x)$ を求めよ．また，求めた $f(x)$ が実際に (＊) をみたすことを示せ．
\end{enumerate}

$f(x)=e^{\frac x2}\cos x$ とする．
\begin{enumerate}
  \item $0\leqq x\leqq1$ のとき，$e^{x}\cos^2x\leqq1+x$ が成り立つことを示せ．
  \item すべての正の整数 $n$ に対して
  \[
  f\!\left(\frac11\right)f\!\left(\frac12\right)f\!\left(\frac13\right)\cdots f\!\left(\frac1n\right)\leqq(n+1)^{a}
  \]
  が成り立つような実数 $a$ の最小値を求めよ．
\end{enumerate}

$f(x)$ は $x^4$ の係数が $1$ で $f(0)=0$ をみたす4次関数とする．実数 $t$ に対し，関数 $|f(x)-tx|$ が微分可能でないような実数 $x$ の個数を $g(t)$ とする．
\begin{enumerate}
  \item $f(x)=x^4-3x^2+x$ のとき，すべての実数 $t$ に対して $g(t)$ を求めよ．また，$g(t)$ が不連続となる $t$ をすべて求めよ．
  \item $g(t)$ が不連続となる $t$ がちょうど $t=1$ と $t=5$ の2つであるような $f(x)$ をすべて求めよ．
\end{enumerate}

実数 $x$ に対し，$x$ を超えない最大の整数を $[x]$ で表す．関数 $f(x)$ を
\[
f(x)=\begin{cases} x-[x] & ([x]\ \text{が偶数のとき})\\[2pt] 2\,(x-[x]) & ([x]\ \text{が奇数のとき})\end{cases}
\]
で定める．多項式 $g(x)$ に対し，合成関数 $g(f(x))$ を考える．
\begin{enumerate}
  \item $g(x)$ が $g(0)=0$ をみたす3次関数であるとき，$g(f(x))$ がすべての実数 $x$ で連続となるような $g(x)$ をすべて求めよ．
  \item $g(x)$ の次数が4以下であり，$g(f(x))$ がすべての実数 $x$ で微分可能であるならば，$g(x)$ は定数であることを示せ．
  \item $g(x)$ が $g(0)=0$ をみたす5次式であるとき，$g(f(x))$ がすべての実数 $x$ で微分可能となるような $g(x)$ をすべて求めよ．
\end{enumerate}

$k$ を正の定数とし，$f(x)=kx^2e^{-x}$ とする．実数 $t$ に対し，曲線 $y=f(x)$ 上の点 $(t,f(t))$ から $x$ 軸までの距離と直線 $y=x$ までの距離を比べ，小さい方（等しいときはその値）を $g(t)$ とする．ただし，$\displaystyle\lim_{t\to\infty}te^{-t}=0$ は用いてよい．
\begin{enumerate}
  \item $k=e$ のとき，$g(t)$ が微分可能でないような実数 $t$ の個数を求めよ．
  \item $g(t)$ が微分可能でないような実数 $t$ の個数を，$k$ の値で場合分けして求めよ．
\end{enumerate}

$x^4$ の係数が $-1$ である4次関数 $g(x)$ に対し，
\[
f(x)=\frac{g(x)}{x^2}\qquad(x>0)
\]
とする．$f(x)$ と $g(x)$ は次の2つの条件をみたす．
\begin{itemize}
  \item[(i)] $f(x)$ は $x=7$ と $x=25$ でともに極大値 $M$ をとる．
  \item[(ii)] $f(x)$（$x>0$）が極値をとる $x$ の値の個数は，$g(x)$（$x$ は実数全体）が極値をとる $x$ の値の個数より多い．
\end{itemize}
\begin{enumerate}
  \item $M$ のとりうる値の範囲を求めよ．
  \item $M$ が正の値のうちで最も小さい値をとるとき，$g(x)$ が極値をとる $x$ の値と，その極値を求めよ．
\end{enumerate}

$x^3$ の係数が1である3次関数 $f(x)$ に対し，$g(x)=f(x^3-3x)$ とする．$g(x)$ は次の条件 (i)，(ii) をみたす．
\begin{itemize}
  \item[(i)] $g(x)$ が極小値をとる $x$ の値はちょうど4個あり，それらの極小値はすべて $0$ である．
  \item[(ii)] $g(x)$ の極大値はすべて等しい．
\end{itemize}
\begin{enumerate}
  \item $f(x)$ を求めよ．
  \item 実数 $k$ に対し，$x$ の方程式 $g(x)=k$ の異なる実数解の個数を求めよ．
\end{enumerate}

$f(x)=x^4+px^3+qx^2+rx+s$（$p,q,r,s$ は実数）とし，$k$ を実数の定数とする．実数全体で定義された関数 $g(x)$ が次の2つの条件をみたすとする．
\begin{itemize}
  \item[(ア)] $0\leqq x<2$ のとき $g(x)=f(x)$．
  \item[(イ)] すべての実数 $x$ について $g(x+2)=g(x)+k$．
\end{itemize}
\begin{enumerate}
  \item $g(x)$ が実数全体で微分可能であるための必要十分条件を，$p,q,r$ と $k$ の関係式で表せ．また，このとき $f(1)-\dfrac{f(0)+f(2)}{2}$ は $p,q,r,s,k$ によらない値であることを示し，その値を求めよ．
  \item $g(x)$ が実数全体で微分可能であり，かつ実数全体で増加する（$x_1<x_2$ ならば $g(x_1)<g(x_2)$ となる）ような $k$ の最小値を求めよ．また，$k$ がその最小値をとるときの $f(x)$ をすべて求めよ．
\end{enumerate}

$f(x)=\log x+\dfrac4x\ (x>0)$ とする．ただし $\log$ は自然対数を表す．
\begin{enumerate}
  \item 曲線 $y=f(x)$ の接線のうち傾きが正であるものについて，その $y$ 切片のとりうる値の範囲を求めよ．
  \item 実数 $a$ について，次の条件 (*) が成り立つための必要十分条件を求めよ．
  \begin{center}
  (*)\ \ すべての正の数 $k$ に対して，直線 $y=kx+a$ と曲線 $y=f(x)$ の共有点はただ1つである．
  \end{center}
\end{enumerate}

$a$ を $0$ でない実数とし，$x>0$ で定義された関数 $f(x)=a\log x+\sqrt{x+1}$ を考える．条件
\[
(\ast)\qquad\text{すべての正の実数 } x \text{ に対して } f(x)\leqq\frac{\sqrt x}{2a}
\]
について，次の問いに答えよ．ただし $e=2.718\cdots$ は自然対数の底であり，$\log$ は自然対数を表す．
\begin{enumerate}
  \item $(\ast)$ が成り立つならば $0<a\leqq\dfrac{\sqrt2}4$ であることを示せ．
  \item $\dfrac14\leqq a\leqq\dfrac{\sqrt2}4$ ならば $(\ast)$ が成り立つことを示せ．
  \item $a=\dfrac1{10}$ のとき $(\ast)$ は成り立たないことを示せ．
\end{enumerate}

$b>e^4$ とし，$f(x)=e^x-bx+e^2$ とする．ただし $e$ は自然対数の底，$\log$ は自然対数を表し，$L=\log b$ とおく．
\begin{enumerate}
  \item $f(x)=0$ はちょうど2つの実数解 $x_1,\ x_2\ (x_1<x_2)$ をもち，$0<x_1<1$，$L<x_2<L+2\log L$ であることを示せ．
  \item $x_2>\dfrac{bL}{e^2+1}\,x_1$ であることを示せ．
  \item $0<c<e^2+1$ をみたす任意の定数 $c$ に対して，ある $b>e^4$ では $x_2<\dfrac{bL}{c}\,x_1$ となることを示せ．
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=(x^2+1)(2x-3)$
  \item $y=\dfrac{x}{x^2+1}$
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=(2x+1)^5$
  \item $y=\sqrt{x^2+3}$
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=\sin^2x$
  \item $y=\tan3x$
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=xe^{2x}$
  \item $y=\log(x^2+1)$
\end{enumerate}

関数 $f(x)=\dfrac{x^2+3}{x+1}$ について．\begin{enumerate}
  \item $f(x)$ の極値と，そのときの $x$ の値を求めよ．
  \item 曲線 $y=f(x)$ の漸近線のうち，$y$ 軸に平行でないものの方程式を求めよ．
\end{enumerate}

関数 $f(x)=\dfrac{\log x}{x}\ (x>0)$ について．\begin{enumerate}
  \item $f(x)$ の極大値を求めよ．
  \item 定数 $a>0$ について，方程式 $\log x=ax$ が異なる2つの正の実数解をもつような $a$ の値の範囲を求めよ．
\end{enumerate}

原点から曲線 $y=e^x$ に引いた接線について．\begin{enumerate}
  \item 接点の座標を求めよ．
  \item 接線の方程式を求めよ．
\end{enumerate}

座標平面上を動く点 P の時刻 $t$ における座標が $x=e^t\cos t,\ y=e^t\sin t$ で表されるとき．\begin{enumerate}
  \item 時刻 $t$ における P の速さを求めよ．
  \item 時刻 $t$ における P の加速度の大きさを求めよ．
\end{enumerate}

次の問いに答えよ．\begin{enumerate}
  \item $x$ が $0$ に近いとき，$\sqrt{1+x}$ の1次の近似式を求めよ．
  \item (1) を用いて $\sqrt{102}$ の近似値を求めよ．
\end{enumerate}

関数 $f(x)=x^3+x$ の逆関数を $g(x)$ とする．\begin{enumerate}
  \item $g(2)$ の値を求めよ．
  \item $g'(2)$ の値を求めよ．
\end{enumerate}

次の問いに答えよ．\begin{enumerate}
  \item 関数 $f(x)=x-\log(1+x)$ の $x\geqq0$ における最小値を求めよ．
  \item $x>0$ のとき，不等式 $x-\dfrac{x^2}{2}<\log(1+x)$ が成り立つことを証明せよ．
\end{enumerate}

曲線 $x^2+xy+y^2=3$ について．\begin{enumerate}
  \item $x+2y\neq0$ のとき，$\dfrac{dy}{dx}$ を $x,\ y$ の式で表せ．
  \item 曲線上の点 $(1,\ 1)$ における接線の方程式を求めよ．
\end{enumerate}

半径 $1$ の球に内接する直円柱について．\begin{enumerate}
  \item 円柱の体積が最大となるときの円柱の高さを求めよ．
  \item 円柱の体積の最大値を求めよ．
\end{enumerate}

関数 $f(x)=x^2e^{-x}$ について．\begin{enumerate}
  \item $f(x)$ の極大値と極小値を求めよ．
  \item 曲線 $y=f(x)$ の変曲点の $x$ 座標をすべて求めよ．
\end{enumerate}
